'use strict';
/* Faith Community Church – browser demo. All data is fictional and stored only in this browser (localStorage). */
const LS = 'fcc_demo_state_v1';
const $ = (s, r = document) => r.querySelector(s);
const clone = o => JSON.parse(JSON.stringify(o));
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const uid = p => p + Date.now().toString(36) + Math.floor(Math.random() * 99);

function fresh() {
  return { onboarded: false, session: null, creds: clone(CREDS), settings: { theme: 'light', lang: 'en', remember: true, biometric: false, wifiOnly: true, offline: false, notif: { announcements: true, events: true, live: true, jumuiya: true, giving: true, admin: true } }, db: clone(SEED), rsvps: {}, saved: [], watched: [], annRead: [], reminders: {}, plans: {}, verses: [], checkins: [], applications: [], downloaded: [], alertAck: [], homeDismissed: [], profileEdits: {} };
}
function load() { try { const p = JSON.parse(localStorage.getItem(LS) || 'null'); if (p) { const f = fresh(); return Object.assign(f, p, { settings: Object.assign(f.settings, p.settings || {}), db: Object.assign(f.db, p.db || {}) }); } } catch (e) { } return fresh(); }
let S = load();
const save = () => { try { localStorage.setItem(LS, JSON.stringify(S)); } catch (e) { } };
const UI = { gf: { range: 'all', fund: 'all', status: 'all', q: '', from: '', to: '', page: 1 }, seen: {}, q: {}, jtab: 'overview' };

