const LOGO = (s = 90) => `<svg width="${s}" height="${s}" viewBox="0 0 100 100" role="img" aria-label="Church logo"><defs><linearGradient id="lg" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#F5CF65"/><stop offset="1" stop-color="#D4AF37"/></linearGradient></defs><path d="M50 4l38 14v30c0 24-17 40-38 48C29 88 12 72 12 48V18z" fill="#071B49" stroke="url(#lg)" stroke-width="4"/><path d="M50 22v50M34 38h32" stroke="url(#lg)" stroke-width="8" stroke-linecap="round"/><path d="M26 76c8 4 16 5 24 5s16-1 24-5" stroke="#F5CF65" stroke-width="2" fill="none" opacity=".7"/></svg>`;
