const art = (seed, em, cls = '', st = '') => `<div class="art ${cls}" style="background:linear-gradient(135deg,${pick(grads, seed)});${st}" role="img" aria-label="Illustration"><span>${em}</span></div>`;
const hash = s => [...String(s)].reduce((a, c) => (a * 31 + c.charCodeAt(0)) | 0, 7);

/* ---------- components ---------- */
const hdr = (title, right = '', backBtn = true) => `<div class="hdr">${backBtn ? `<button class="ib" data-a="back" aria-label="Back">${ic('back')}</button>` : ''}<h1>${esc(title)}</h1>${right}</div>`;
const badge = (txt, k = '') => `<span class="badge ${k}">${esc(txt)}</span>`;
const stClass = s => ({ Verified: 'ok', Pending: 'warn', Failed: 'err', Rejected: 'err', Approved: 'ok', Declined: 'err', Active: 'ok', Inactive: 'warn', Suspended: 'err' }[s] || '');
const empty = (icon, title, msg, btn = '') => `<div class="empty"><div class="ico">${ic(icon, 'lg')}</div><b>${esc(title)}</b><p class="muted" style="margin:6px 0 14px">${esc(msg)}</p>${btn}</div>`;
const errState = (retry = 'refresh') => empty('alert', 'Can’t connect', 'You appear to be offline (simulated). Downloaded items are still available.', `<button class="btn btn-blue sm" data-a="${retry}">Try again</button>`);
const search = (id, ph, val) => `<div class="search">${ic('search', 'sm')}<input id="${id}" data-in="q.${id}" placeholder="${ph}" value="${esc(val || '')}" aria-label="${ph}"></div>`;
const chips = (items, on, path) => `<div class="chips">${items.map(([v, l]) => `<button class="chip ${v === on ? 'on' : ''}" data-a="setui" data-p="${path}" data-v="${esc(v)}">${esc(l)}</button>`).join('')}</div>`;
const ring = (pct, size = 84) => { const r = 40, c = 2 * Math.PI * r; return `<div class="ring" style="width:${size}px;height:${size}px"><svg viewBox="0 0 100 100" width="${size}" height="${size}" style="transform:rotate(-90deg)"><defs><linearGradient id="rg${pct}${size}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#0B3D91"/><stop offset="1" stop-color="#D4AF37"/></linearGradient></defs><circle class="tr" cx="50" cy="50" r="${r}"/><circle class="pg" cx="50" cy="50" r="${r}" stroke="url(#rg${pct}${size})" stroke-dasharray="${c}" stroke-dashoffset="${c * (1 - pct / 100)}"/></svg><b>${pct}%</b></div>`; };
const tog = (path, on) => `<button class="switch ${on ? 'on' : ''}" role="switch" aria-checked="${!!on}" data-a="tog" data-k="${path}"></button>`;
const demoNote = '<div class="notice">ⓘ <span>Demo data: fictional sample records, not official church records.</span></div>';
const sheet = html => { $('#overlay').innerHTML = `<div class="back" data-a="backdrop"><div class="sheet"><div class="grab"></div>${html}</div></div>`; };
const closeSheet = () => { $('#overlay').innerHTML = ''; };
let pendingCb = null;
const confirmBox = (msg, cb, label = 'Confirm') => { pendingCb = cb; sheet(`<h3>Are you sure?</h3><p class="muted" style="margin-bottom:16px">${esc(msg)}</p><div class="inl"><button class="btn btn-ghost" data-a="closeSheet">Cancel</button><button class="btn btn-red" data-a="doConfirm">${label}</button></div>`); };

/* charts */
function barChart(labels, vals, fmt = v => v, h = 150) {
  const w = 320, max = Math.max(...vals, 1), bw = w / labels.length;
  return `<svg class="chart" viewBox="0 0 ${w} ${h + 22}" role="img" aria-label="Bar chart"><defs><linearGradient id="bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D4AF37"/><stop offset="1" stop-color="#0B3D91"/></linearGradient></defs>${vals.map((v, i) => { const bh = Math.max(2, v / max * (h - 18)); return `<rect x="${i * bw + bw * .18}" y="${h - bh}" width="${bw * .64}" height="${bh}" rx="4" fill="url(#bg)"/><text x="${i * bw + bw / 2}" y="${h + 12}" text-anchor="middle">${esc(String(labels[i]).slice(0, 5))}</text>`; }).join('')}<text x="2" y="9">max ${fmt(max)}</text></svg>`;
}
function lineChart(labels, vals, h = 130) {
  const w = 320, max = Math.max(...vals, 1), min = Math.min(...vals) * .9, st = w / Math.max(1, vals.length - 1);
  const pts = vals.map((v, i) => [i * st, h - (v - min) / (max - min || 1) * (h - 14) - 4]);
  const d = pts.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join(' ');
  return `<svg class="chart" viewBox="-6 0 ${w + 12} ${h + 20}" role="img" aria-label="Line chart"><defs><linearGradient id="la" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D4AF37" stop-opacity=".45"/><stop offset="1" stop-color="#0B3D91" stop-opacity="0"/></linearGradient></defs><path d="${d} L${w} ${h} L0 ${h}Z" fill="url(#la)"/><path d="${d}" fill="none" stroke="#0B3D91" stroke-width="2.5"/>${pts.map(p => `<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="#D4AF37"/>`).join('')}${labels.map((l, i) => i % Math.ceil(labels.length / 6) === 0 ? `<text x="${i * st}" y="${h + 14}" text-anchor="middle">${esc(l)}</text>` : '').join('')}</svg>`;
}
function qrSvg(token) { // decorative pseudo-QR from a revocable token (NOT a scannable code)
  const n = 21; let seed = Math.abs(hash(token)) || 1; const rnd = () => (seed = (seed * 1103515245 + 12345) & 0x7fffffff) / 0x7fffffff;
  let cells = ''; const fin = (x, y) => (x < 8 && y < 8) || (x > n - 9 && y < 8) || (x < 8 && y > n - 9);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) { let on; if (fin(x, y)) { const lx = x % (n - 7 + (x > 12 ? 0 : 0)), ly = y > 12 ? y - 13 : y; const ax = x > 12 ? x - 13 : x; on = ax === 0 || ax === 6 || ly === 0 || ly === 6 || (ax >= 2 && ax <= 4 && ly >= 2 && ly <= 4); if (ax > 6 || ly > 6) on = false; } else on = rnd() > .52; if (on) cells += `<rect x="${x}" y="${y}" width="1" height="1"/>`; }
  return `<svg viewBox="0 0 ${n} ${n}" width="150" height="150" fill="#071B49" role="img" aria-label="Demo membership QR placeholder">${cells}</svg>`;
}

/* ---------- router ---------- */
const SC = {}; const TABS = ['home', 'giving', 'services', 'community', 'profile'];
const LOADING = ['announcements', 'services', 'documents', 'events'];
let stack = [{ n: 'splash', p: {} }], lastKey = '';
const go = (n, p = {}) => { stack.push({ n, p }); history.pushState({ d: stack.length }, ''); render(); };
const back = () => { if (stack.length > 1) { stack.pop(); render(); } };
const tab = n => { stack = [{ n, p: {} }]; render(); };
const reset = (n, p = {}) => { stack = [{ n, p }]; render(); };
window.addEventListener('popstate', () => { if (stack.length > 1) { stack.pop(); render(); } });

function render() {
  const c = stack[stack.length - 1]; const sc = $('#screen'); const f = document.activeElement; const fid = f && f.id, fs = f && f.selectionStart;
  document.documentElement.dataset.theme = S.settings.theme; document.documentElement.lang = S.settings.lang;
  const nav = $('#nav'); nav.style.display = TABS.includes(c.n) ? 'flex' : 'none';
  nav.innerHTML = [['home', 'home'], ['giving', 'heart'], ['services', 'video'], ['community', 'users'], ['profile', 'user']].map(([k, i]) => `<button class="${c.n === k ? 'on' : ''}" data-a="tab" data-to="${k}" aria-label="${t(k)}">${ic(i)}<span>${t(k)}</span></button>`).join('');
  if (LOADING.includes(c.n) && !UI.seen[c.n]) { sc.innerHTML = hdr(c.n[0].toUpperCase() + c.n.slice(1), '', !TABS.includes(c.n)) + '<div class="skel"></div><div class="skel"></div><div class="skel"></div>'; setTimeout(() => { UI.seen[c.n] = 1; if (stack[stack.length - 1] === c) render(); }, 450); return; }
  const prev = sc.scrollTop; const key = c.n + stack.length;
  let html; try { html = SC[c.n](c.p || {}); } catch (e) { console.error(e); html = hdr('Something went wrong') + empty('alert', 'Unexpected error', String(e.message)); }
  sc.innerHTML = `<div class="fade">${html}</div>`; sc.scrollTop = key === lastKey ? prev : 0; lastKey = key;
  if (fid) { const el = document.getElementById(fid); if (el) { el.focus(); try { el.setSelectionRange(fs, fs); } catch (e) { } } }
}

/* ---------- events ---------- */
const A = {};
document.addEventListener('click', e => { const el = e.target.closest('[data-a]'); if (el && A[el.dataset.a]) A[el.dataset.a](el.dataset, el); });
const onIn = e => { const el = e.target; if (el.dataset && el.dataset.in) { setPath(UI, el.dataset.in, el.value); if (el.dataset.in.startsWith('gf.') && el.dataset.in !== 'gf.page') UI.gf.page = 1; render(); } if (el.dataset && el.dataset.set) { setPath(S, el.dataset.set, el.value); save(); render(); } };
document.addEventListener('input', e => { if (e.target.tagName === 'INPUT' && e.target.type !== 'date') onIn(e); });
document.addEventListener('change', e => { if (e.target.tagName === 'SELECT' || e.target.type === 'date') onIn(e); });
const FORMS = {};
document.addEventListener('submit', e => { e.preventDefault(); const f = e.target; if (FORMS[f.dataset.f]) { const d = Object.fromEntries(new FormData(f)); FORMS[f.dataset.f](d, f); } });
Object.assign(A, {
  back, closeSheet, backdrop: (d, el) => { if (event.target === el) closeSheet(); }, go: d => go(d.to, d.id ? { id: d.id } : (d.p ? JSON.parse(d.p) : {})), tab: d => tab(d.to),
  setui: d => { setPath(UI, d.p, d.v); if (d.p.startsWith('gf.')) UI.gf.page = 1; render(); },
  tog: d => { const cur = d.k.split('.').reduce((o, k) => o[k], S); setPath(S, d.k, !cur); save(); if (d.k === 'settings.biometric') toast('Biometric unlock is simulated in this web demo'); render(); },
  doConfirm: () => { closeSheet(); if (pendingCb) pendingCb(); pendingCb = null; }, refresh: () => { UI.seen = {}; render(); toast('Refreshed'); },
  setSet: d => { setPath(S, d.p, d.v); save(); render(); }
});

/* ============ SPLASH / ONBOARDING / AUTH ============ */
SC.splash = () => { setTimeout(() => { if (stack[0].n === 'splash' && stack.length === 1) startFlow(); }, 2600); return `<div class="auth splash" data-a="skipSplash"><div class="bg"></div><div class="logo">${LOGO(110)}</div><h1 style="margin-top:12px">Faith Community Church</h1><div class="gline"></div><p style="letter-spacing:.5px">Connecting Faith &amp; Community</p><p class="small" style="opacity:.8;max-width:260px;margin-top:26px;font-family:Georgia,serif">“Behold, how good and how pleasant it is for brethren to dwell together in unity!” <br>— Psalm 133:1 (KJV)</p><div class="spin"></div><p class="small" style="position:absolute;bottom:18px;opacity:.6">Demo mode · fictional data</p></div>`; };
function startFlow() { if (!S.onboarded) reset('onboarding'); else if (S.session && S.settings.remember) reset('home'); else reset('login'); }
A.skipSplash = startFlow;
const OB = [['🙏', 'Stay connected to your church', 'Receive announcements, alerts and encouragement from your church family.'], ['📺', 'Follow online services and events', 'Watch sermons, join live services and RSVP to upcoming events.'], ['💛', 'Track your offerings and pledges', 'See your giving history and pledge progress in one secure place.'], ['🏡', 'Connect with your Jumuiya', 'Meet with your home fellowship, share prayer requests and stay in touch.']];
SC.onboarding = () => { const i = UI.ob || 0, o = OB[i]; return `<div class="auth"><div style="text-align:right"><button data-a="obDone" style="color:#F5CF65;font-weight:600">Skip</button></div>${art(i + 1, o[0], 'ob-art', 'font-size:80px')}<h2 style="font-size:26px">${o[1]}</h2><p style="opacity:.85;margin-top:8px;line-height:1.5">${o[2]}</p><div style="flex:1"></div><div class="dots">${OB.map((_, k) => `<i class="${k === i ? 'on' : ''}"></i>`).join('')}</div><button class="btn btn-gold" data-a="${i < 3 ? 'obNext' : 'obDone'}">${i < 3 ? 'Next' : 'Get Started'}</button></div>`; };
A.obNext = () => { UI.ob = (UI.ob || 0) + 1; render(); }; A.obDone = () => { S.onboarded = true; save(); reset('login'); };

SC.login = () => `<div class="auth"><div style="text-align:center;margin-top:6px">${LOGO(74)}<h2 style="margin-top:8px">Welcome back</h2><p style="opacity:.8;font-size:13px">Sign in to Faith Community Church</p></div>
<div class="card" style="margin-top:18px"><form data-f="login" novalidate>
<label class="lbl" for="ch">Church Code</label><input class="inp ${UI.le && UI.le.ch ? 'bad' : ''}" id="ch" name="ch" value="${esc(UI.lv?.ch || '')}" placeholder="e.g. FCC123" autocapitalize="characters">${UI.le?.ch ? `<div class="err">${UI.le.ch}</div>` : ''}${UI.lv?.ch && UI.lv.ch.toUpperCase() === S.db.church.code ? `<div class="small" style="color:var(--ok);margin-top:4px">✔ ${esc(S.db.church.name)}</div>` : ''}
<label class="lbl" for="mc">Member Code</label><input class="inp ${UI.le?.mc ? 'bad' : ''}" id="mc" name="mc" value="${esc(UI.lv?.mc || '')}" placeholder="e.g. MEM10045" autocapitalize="characters">${UI.le?.mc ? `<div class="err">${UI.le.mc}</div>` : ''}
<label class="lbl" for="pw">Password</label><div class="pw"><input class="inp ${UI.le?.pw ? 'bad' : ''}" id="pw" name="pw" type="${UI.showPw ? 'text' : 'password'}" placeholder="Password" autocomplete="current-password"><button type="button" data-a="showPw" aria-label="Toggle password visibility">${ic('eye')}</button></div>${UI.le?.pw ? `<div class="err">${UI.le.pw}</div>` : ''}
${UI.lerr ? `<div class="err" role="alert" style="margin-top:10px">${UI.lerr}</div>` : ''}
<label class="check"><input type="checkbox" name="remember" ${S.settings.remember ? 'checked' : ''}> Remember this device</label>
<button class="btn btn-gold" ${UI.busy ? 'disabled' : ''}>${UI.busy ? 'Signing in…' : 'Login'}</button></form>
<p style="text-align:center;margin-top:12px"><a class="link" data-a="go" data-to="forgot">Forgot Password?</a></p></div>
<div class="notice" style="background:rgba(255,255,255,.12);color:#fff;margin-top:6px">ⓘ <span><b>Demo mode.</b> Credentials below are demo-only. Production uses Firebase Authentication and a server-verified member record.</span></div>
<button class="btn btn-ghost" data-a="demoLogin" data-code="MEM10045">Enter Demo as Member (Collin)</button>
<button class="btn" style="color:#F5CF65;margin-top:6px" data-a="demoLogin" data-code="ADM001">Enter Demo as Administrator</button>
<p style="text-align:center;font-size:12px;opacity:.85;margin-top:8px">Other demo staff: TRS001 · PST001 · ADM002 (pw admin1234)<br><a class="link" style="color:#F5CF65" data-a="contactAdmin">Contact Church Administrator</a></p></div>`;
A.showPw = () => { UI.showPw = !UI.showPw; const v = { ch: $('#ch').value, mc: $('#mc').value }; UI.lv = v; render(); };
A.contactAdmin = () => sheet(`<h3>Contact Church Administrator</h3><p class="muted">${esc(S.db.church.name)} office (fictional)</p><div class="row"><div class="g"><b>${S.db.church.phone}</b><span class="muted">Mon–Fri 9:00–16:00</span></div><a class="btn btn-ghost sm" href="tel:${S.db.church.phone.replace(/\s/g, '')}">Call</a></div><div class="row"><div class="g"><b>${S.db.church.email}</b></div><a class="btn btn-ghost sm" href="mailto:${S.db.church.email}">Email</a></div>`);
function doLogin(code, role) { S.session = { code, role }; save(); logAudit && 0; reset('home'); toast('Signed in (demo)'); }
FORMS.login = d => {
  if (UI.busy) return; UI.lv = { ch: d.ch, mc: d.mc }; S.settings.remember = !!d.remember; const e = {};
  if (!d.ch.trim()) e.ch = 'Church code is required'; else if (d.ch.trim().toUpperCase() !== S.db.church.code) e.ch = 'Church code not recognised';
  if (!d.mc.trim()) e.mc = 'Member code is required'; if (!d.pw) e.pw = 'Password is required';
  UI.le = e; UI.lerr = ''; if (Object.keys(e).length) return render();
  UI.busy = true; render();
  setTimeout(() => { UI.busy = false; const c = S.creds.find(x => x.code === d.mc.trim().toUpperCase()); if (!c || c.pw !== d.pw) { UI.lerr = 'Invalid church code, member code or password.'; return render(); } UI.le = {}; UI.lv = null; doLogin(c.code, c.role); }, 900);
};
A.demoLogin = d => { UI.le = {}; UI.lerr = ''; const c = S.creds.find(x => x.code === d.code); doLogin(c.code, c.role); };

SC.forgot = () => `<div class="auth">${hdrAuth('Forgot Password')}<div class="card"><p class="muted">Enter your church code and member code. In production a reset link is sent by Firebase Authentication to your registered email.</p><form data-f="forgot"><label class="lbl" for="fc">Church Code</label><input class="inp" id="fc" name="ch" required><label class="lbl" for="fm">Member Code</label><input class="inp" id="fm" name="mc" required><div style="height:14px"></div><button class="btn btn-gold">Send reset link</button></form></div></div>`;
const hdrAuth = t => `<div style="display:flex;align-items:center;gap:8px;margin-bottom:18px"><button class="ib" data-a="back" aria-label="Back" style="color:#fff">${ic('back')}</button><h2>${t}</h2></div>`;
FORMS.forgot = d => { const c = S.creds.find(x => x.code === d.mc.trim().toUpperCase()); if (d.ch.trim().toUpperCase() !== S.db.church.code || !c) return toast('Details not found'); go('reset', { id: c.code }); toast('Demo: no email was actually sent'); };
SC.reset = p => `<div class="auth">${hdrAuth('Reset Password')}<div class="card"><div class="notice">ⓘ Demo only: no email was sent. In production this step uses a secure, expiring reset link.</div><form data-f="reset"><input type="hidden" name="code" value="${esc(p.id)}"><label class="lbl" for="np">New password (min 8 characters)</label><input class="inp" id="np" name="np" type="password" required><label class="lbl" for="np2">Confirm password</label><input class="inp" id="np2" name="np2" type="password" required><div style="height:14px"></div><button class="btn btn-gold">Reset password</button></form></div></div>`;
FORMS.reset = d => { if (d.np.length < 8) return toast('Password must be at least 8 characters'); if (d.np !== d.np2) return toast('Passwords do not match'); S.creds.find(x => x.code === d.code).pw = d.np; save(); reset('login'); toast('Password updated (demo)'); };

/* ============ HOME ============ */
SC.home = () => {
  const m = me(), unread = S.db.notifications.filter(n => !n.read).length, h = new Date().getHours(), gr = h < 12 ? t('gm') : h < 17 ? t('ga') : t('ge');
  const v = verseOfDay();
  const dismissed = S.homeDismissed || [];
  const priorityItems = [
    ...S.db.alerts.filter(x => !S.alertAck.includes(x.id)).map(x => ({ id: x.id, kind: 'alert', title: x.title, body: x.body, date: x.date, priority: x.priority || 'High' })),
    ...anns().filter(x => x.priority === 'High').map(x => ({ id: x.id, kind: 'announcement', title: x.title, body: x.body, date: x.date, priority: 'High' }))
  ].filter(x => !dismissed.includes(`${x.kind}:${x.id}`)).sort((a, b) => new Date(b.date) - new Date(a.date));
  const quickActions = [
    ['heart', t('tithes'), 'give', 'tithes'], ['gift', t('offerings'), 'give', 'sunday'],
    ['home', t('building'), 'give', 'building'], ['star', t('pledges'), 'pledges'],
    ['video', 'Online Services', 'tabS'], ['cal', 'Events', 'events'],
    ['file', t('docs'), 'documents'], ['users', t('lead'), 'leadership']
  ];
  return `<div class="hero home-hero"><div class="top"><div class="avatar">${initials(m.name)}</div><div class="home-greeting"><small>${gr},</small><h2>${esc(m.name.split(' ')[0])}</h2><small>${esc(S.db.church.name)} · ${fd(new Date().toISOString(), { weekday: 'short', day: 'numeric', month: 'short' })}</small></div><button class="ib home-bell" data-a="go" data-to="notifications" aria-label="Notifications">${ic('bell')}${unread ? `<span class="dot">${unread}</span>` : ''}</button></div></div>
<div class="home-content">
${priorityItems.length ? `<section class="home-priority"><div class="home-section-title"><span class="priority-pulse"></span><span>HIGH PRIORITY</span><span class="priority-count">${priorityItems.length}</span></div>${priorityItems.map(n => `<button class="priority-notice ${n.kind === 'alert' ? 'is-alert' : ''}" data-a="dismissHomeNotice" data-kind="${n.kind}" data-id="${esc(n.id)}"><span class="priority-icon">${ic(n.kind === 'alert' ? 'alert' : 'bell')}</span><span class="priority-copy"><b>${esc(n.title)}</b><small>${esc(n.body)}</small></span><span class="priority-dismiss" aria-label="Dismiss">${ic('x')}</span></button>`).join('')}</section>` : ''}
<section class="home-quick"><div class="home-section-title">${t('quick')}</div><div class="grid4 home-grid">${quickActions.map(q => `<button class="qa" ${q[2] === 'tabS' ? 'data-a="tab" data-to="services"' : `data-a="go" data-to="${q[2]}" ${q[3] ? `data-id="${q[3]}"` : ''}`}><span class="qa-gold-icon">${ic(q[0])}</span><span class="qa-label">${q[1]}</span></button>`).join('')}</div></section>
<section class="home-verse"><div class="home-section-title">${t('scr')}</div><div class="scr home-scripture"><div class="verse-ornament">✦</div><small class="verse-reference">${v.ref} · KJV</small><q>${esc(v.text)}</q><div class="verse-footer"><span>✝</span><button class="btn btn-gold sm" data-a="shareVerse" data-r="${v.ref}">${ic('share', 'sm')} Share verse</button></div></div></section>
</div>`;
};
A.dismissHomeNotice = d => { if (!S.homeDismissed) S.homeDismissed = []; const key = `${d.kind}:${d.id}`; if (!S.homeDismissed.includes(key)) S.homeDismissed.push(key); save(); render(); toast('Notification dismissed'); };
A.shareVerse = d => { const v = VERSES.find(x => x.ref === d.r); share(v.ref, `“${v.text}” — ${v.ref} (KJV) · ${S.db.church.name}`); };
const txRow = x => `<div class="row tap" data-a="go" data-to="txn" data-id="${x.id}"><div class="ico">${fundIcon(x.fund)}</div><div class="g"><b>${fundName(x.fund)}</b><span class="muted small">${fd(x.date)} · ${x.method}</span></div><div style="text-align:right"><b>${money(x.amount)}</b><br>${badge(x.status, stClass(x.status))}</div></div>`;
A.rsvpQuick = (d, el) => { event.stopPropagation(); toggleRsvp(d.id); };
function toggleRsvp(id) { if (S.rsvps[id]) { confirmBox('Cancel your registration for this event?', () => { delete S.rsvps[id]; save(); render(); toast('Registration cancelled'); }, 'Cancel registration'); } else { S.rsvps[id] = { date: new Date().toISOString(), status: 'Registered' }; save(); render(); toast('Registered. This is a demo RSVP saved on this device.'); } }

/* ============ ANNOUNCEMENTS ============ */
SC.announcements = () => { const f = UI.annCat || 'All', q = (UI.q.as || '').toLowerCase(); let l = anns().filter(a => (f === 'All' || a.cat === f) && (a.title + a.body).toLowerCase().includes(q)); const un = anns().filter(a => !S.annRead.includes(a.id)).length;
  return hdr('Announcements', `<button class="btn btn-ghost sm" data-a="markAllAnn">Mark all read</button>`) + search('as', 'Search announcements', UI.q.as) + chips([['All', 'All'], ['Important', 'Important'], ['Events', 'Events'], ['Ministry', 'Ministry'], ['General', 'General']], f, 'annCat') + `<div class="pad" style="padding-top:0"><p class="muted small" style="margin-bottom:8px">${un} unread</p>${l.length ? l.map(a => `<div class="card tap" data-a="go" data-to="annDetail" data-id="${a.id}"><div class="row" style="border:0;padding:0;align-items:flex-start"><div class="ico">${a.img}</div><div class="g"><b style="white-space:normal">${!S.annRead.includes(a.id) ? '<span style="color:var(--gold)">● </span>' : ''}${esc(a.title)}</b><span class="muted small">${a.cat} · ${fd(a.date)} ${a.attach ? '· 📎' : ''}</span></div>${a.priority === 'High' ? badge('Important', 'err') : ''}</div></div>`).join('') : empty('msg', 'No announcements', 'Nothing matches your search or filter.')}</div>`; };
A.markAllAnn = () => { anns().forEach(a => !S.annRead.includes(a.id) && S.annRead.push(a.id)); save(); render(); toast('All announcements marked as read'); };
SC.annDetail = p => { const a = S.db.announcements.find(x => x.id === p.id); if (!a) return hdr('Announcement') + empty('alert', 'Not found', 'This announcement is no longer available.'); const read = S.annRead.includes(a.id);
  return hdr('Announcement', `<button class="ib" data-a="shareAnn" data-id="${a.id}" aria-label="Share">${ic('share')}</button>`) + art(hash(a.id), a.img, '', 'height:150px;font-size:60px') + `<div class="pad"><div style="display:flex;gap:8px;margin-bottom:8px">${badge(a.cat)}${badge(a.priority, a.priority === 'High' ? 'err' : 'gold')}</div><h2>${esc(a.title)}</h2><p class="muted small" style="margin:4px 0 12px">Published ${fdt(a.date)}</p><p style="line-height:1.6">${esc(a.body)}</p>${a.attach ? `<div class="card" style="margin-top:14px"><div class="row" style="border:0;padding:0"><div class="ico">${ic('file')}</div><div class="g"><b>Attachment (demo)</b><span class="muted small">${esc(a.title)}.pdf</span></div><button class="btn btn-ghost sm" data-a="dlGeneric" data-n="${esc(a.title)}.txt">Download</button></div></div>` : ''}<button class="btn ${read ? 'btn-ghost' : 'btn-blue'}" style="margin-top:16px" data-a="toggleAnnRead" data-id="${a.id}">${read ? 'Mark as unread' : 'Mark as read'}</button></div>`; };
A.toggleAnnRead = d => { const i = S.annRead.indexOf(d.id); i < 0 ? S.annRead.push(d.id) : S.annRead.splice(i, 1); save(); render(); };
A.shareAnn = d => { const a = S.db.announcements.find(x => x.id === d.id); share(a.title, a.body); };
A.dlGeneric = d => { dlFile(d.n, `${d.n}\n\nDemo attachment generated by the Faith Community Church demo app.\nFictional content.`); toast('Downloaded (demo file)'); };
// opening an announcement marks it read
const _annDetail = SC.annDetail; SC.annDetail = p => { if (p.id && !S.annRead.includes(p.id)) { S.annRead.push(p.id); save(); } return _annDetail(p); };

/* ============ EVENTS ============ */
const EVCATS = ['All', 'Sunday Services', 'Conferences', 'Prayer Meetings', 'Youth Events', 'Women\'s Ministry', 'Men\'s Ministry', 'Choir Practice', 'Bible Study', 'Fundraising', 'Community Outreach'];
SC.events = () => { const tb = UI.evTab || 'upcoming', cat = UI.evCat || 'All', q = (UI.q.es || '').toLowerCase(), now = new Date();
  let l = evs().filter(e => { const s = new Date(e.start), en = new Date(e.end); return tb === 'upcoming' ? en >= now : tb === 'month' ? sameMonth(s) : tb === 'year' ? s.getFullYear() === now.getFullYear() : en < now; }).filter(e => (cat === 'All' || e.cat === cat) && (e.title + e.venue).toLowerCase().includes(q)); if (tb === 'past') l.reverse();
  return hdr('Events') + `<div class="tabs">${[['upcoming', 'Upcoming'], ['month', 'This Month'], ['year', 'This Year'], ['past', 'Past']].map(([k, l]) => `<button class="${tb === k ? 'on' : ''}" data-a="setui" data-p="evTab" data-v="${k}">${l}</button>`).join('')}</div>` + search('es', 'Search events', UI.q.es) + chips(EVCATS.map(c => [c, c]), cat, 'evCat') + `<div class="pad" style="padding-top:0">${l.length ? l.map(e => `<div class="card tap" style="padding:0;overflow:hidden" data-a="go" data-to="eventDetail" data-id="${e.id}">${art(hash(e.id), e.img, '', 'height:90px')}<div style="padding:14px"><div style="display:flex;justify-content:space-between;gap:8px"><b>${esc(e.title)}</b>${S.rsvps[e.id] ? badge('Registered', 'ok') : new Date(e.end) < now ? badge('Past') : ''}</div><div class="muted small" style="margin-top:4px">${fd(e.start, { weekday: 'short', day: 'numeric', month: 'short' })} · ${ftm(e.start)} – ${ftm(e.end)}</div><div class="muted small">${ic('pin', 'sm')} ${esc(e.venue)}</div></div></div>`).join('') : empty('cal', 'No events found', 'Try another tab, category or search term.')}</div>`; };
SC.eventDetail = p => { const e = S.db.events.find(x => x.id === p.id); if (!e) return hdr('Event') + empty('alert', 'Not found', ''); const past = new Date(e.end) < new Date(), r = S.rsvps[e.id], cnt = e.baseReg + (r ? 1 : 0);
  return hdr('Event Details', `<button class="ib" data-a="shareEv" data-id="${e.id}" aria-label="Share">${ic('share')}</button>`) + art(hash(e.id), e.img, '', 'height:170px;font-size:70px') + `<div class="pad"><span class="badge">${e.cat}</span><h2 style="margin:8px 0">${esc(e.title)}</h2>
<div class="card"><div class="row"><div class="ico">${ic('cal')}</div><div class="g"><b>${fd(e.start, { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' })}</b><span class="muted small">${ftm(e.start)} – ${ftm(e.end)}${fd(e.start) !== fd(e.end) ? ' (until ' + fd(e.end) + ')' : ''}</span></div></div><div class="row"><div class="ico">${ic('pin')}</div><div class="g"><b>${esc(e.venue)}</b><a class="link" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(e.venue + ' ' + S.db.church.mapQuery)}">Get directions</a></div></div><div class="row"><div class="ico">${ic('users')}</div><div class="g"><b>${cnt} registered</b><span class="muted small">Capacity ${e.cap}</span></div></div><div class="row"><div class="ico">${ic('phone')}</div><div class="g"><b>Organizer</b><span class="muted small">${esc(e.organizer)}</span></div></div></div><p style="line-height:1.6">${esc(e.desc)}</p>
<div style="height:12px"></div>${past ? `<button class="btn btn-ghost" disabled>This event has ended</button>` : `<button class="btn ${r ? 'btn-ghost' : 'btn-gold'}" data-a="rsvp" data-id="${e.id}">${r ? '✓ Registered — tap to cancel' : 'RSVP / Register'}</button>`}${r ? `<p class="muted small" style="text-align:center;margin-top:6px">Registered ${fdt(r.date)} · Status: ${r.status}</p>` : ''}<button class="btn btn-blue" style="margin-top:10px" data-a="addCal" data-id="${e.id}">${ic('cal', 'sm')} Add to Calendar</button></div>`; };
A.rsvp = d => toggleRsvp(d.id);
A.shareEv = d => { const e = S.db.events.find(x => x.id === d.id); share(e.title, `${e.title} — ${fdt(e.start)} at ${e.venue}`); };
A.addCal = d => { const e = S.db.events.find(x => x.id === d.id), z = i => new Date(i).toISOString().replace(/[-:]/g, '').split('.')[0] + 'Z'; dlFile(e.title.replace(/\W+/g, '_') + '.ics', `BEGIN:VCALENDAR\r\nVERSION:2.0\r\nBEGIN:VEVENT\r\nUID:${e.id}@faithcommunity.demo\r\nDTSTART:${z(e.start)}\r\nDTEND:${z(e.end)}\r\nSUMMARY:${e.title}\r\nLOCATION:${e.venue}\r\nDESCRIPTION:${e.desc}\r\nEND:VEVENT\r\nEND:VCALENDAR`, 'text/calendar'); toast('Calendar file downloaded'); };

/* ============ GIVING ============ */
SC.giving = () => { const vf = verified(), bf = byFund(vf), tot = sum(vf) || 1, ps = myPledges();
  return `<div class="hero" style="padding-bottom:64px"><h2>${t('giving')}</h2><small>Verified records only</small></div><div class="up">${demoNote}<div class="card blue glow"><div class="small" style="opacity:.8">Given this month</div><div class="big">${money(monthTotal())}</div><div class="small" style="opacity:.8;margin-top:8px">This year</div><div class="b" style="font-size:20px">${money(yearTotal())}</div></div>
<div class="inl" style="margin-bottom:14px"><button class="btn btn-gold" data-a="go" data-to="give">${ic('heart', 'sm')} Give</button><button class="btn btn-ghost" data-a="go" data-to="history">History</button></div>
<div class="card"><div class="b" style="margin-bottom:10px">Giving by fund</div>${bf.length ? bf.map(([f, v]) => `<div style="margin-bottom:10px"><div style="display:flex;justify-content:space-between;font-size:13px"><span>${fundIcon(f)} ${fundName(f)}</span><b>${money(v)}</b></div><div class="bar" style="margin-top:4px"><i style="width:${v / tot * 100}%"></i></div></div>`).join('') : '<p class="muted">No verified giving records.</p>'}</div>
<div class="card tap" data-a="go" data-to="pledges"><div class="row" style="border:0;padding:0"><div class="ico gold">${ic('star')}</div><div class="g"><b>My Pledges</b><span class="muted small">${ps.length} pledge${ps.length === 1 ? '' : 's'} · ${money(sum(ps.map(p => ({ amount: p.total - pledgePaid(p) }))))} outstanding</span></div>${ic('chev')}</div></div>
<div class="sec" style="margin:8px 0"><span>Recent transactions</span><a data-a="go" data-to="history">View all</a></div><div class="card">${myTx().length ? myTx().slice().sort((a, b) => new Date(b.date) - new Date(a.date)).slice(0, 5).map(txRow).join('') : '<p class="muted">No giving records for this account.</p>'}</div></div>`; };
SC.give = p => { const f = UI.giveFund || p.id || 'tithes'; return hdr('Give') + `<div class="pad"><div class="notice">⚠️ <span><b>No real payment is processed here.</b> Payments must be made using the church’s official channels. The button below only creates a clearly labelled <i>simulated, pending</i> record in this demo. It is never counted as received.</span></div>
<label class="lbl" for="gf">Fund</label><select class="inp" id="gf" data-in="giveFund">${S.db.funds.map(x => `<option value="${x.id}" ${x.id === f ? 'selected' : ''}>${x.name}</option>`).join('')}</select>
<div class="card" style="margin-top:14px"><div class="b">Payment instructions</div><p class="muted small" style="margin:6px 0">Mobile money: Lipa Namba <b>000000</b> (placeholder)<br>Bank: ${esc(S.db.church.name)} · A/C <b>0000000000</b> (placeholder)<br>Reference: <b>${me().code}-${f.toUpperCase().slice(0, 3)}</b><br>Or give at the church office during opening hours.</p></div>
<form data-f="give"><input type="hidden" name="fund" value="${f}"><label class="lbl" for="ga">Amount (${cur()})</label><input class="inp" id="ga" name="amount" type="number" min="1000" step="500" placeholder="e.g. 50000" required><div style="height:14px"></div><button class="btn btn-blue">Create simulated record (demo)</button></form></div>`; };
FORMS.give = d => { const a = +d.amount; if (!(a >= 1000)) return toast('Enter at least 1,000'); S.db.transactions.unshift({ id: 'TX-' + (1000 + S.db.transactions.length + 25), mc: me().code, fund: d.fund, amount: a, date: new Date().toISOString(), method: 'Simulated (demo)', ref: 'SIM-' + Date.now().toString().slice(-6), status: 'Pending', pledge: '', source: 'Demo simulation – not a real payment' }); save(); back(); toast('Simulated pending record created. No payment was made.'); };
SC.history = () => { const g = UI.gf, l = filterTx(g), shown = l.slice(0, g.page * 10);
  return hdr('Giving History', `<button class="ib" data-a="stmt" aria-label="Download statement">${ic('dl')}</button>`) + search('gq', 'Search fund, method, reference', g.q).replace('data-in="q.gq"', 'data-in="gf.q"') + `<div style="padding:0 16px"><div class="inl"><select class="inp" data-in="gf.range" aria-label="Date range">${[['all', 'All time'], ['today', 'Today'], ['month', 'This month'], ['year', 'This year'], ['custom', 'Custom range']].map(([v, n]) => `<option value="${v}" ${g.range === v ? 'selected' : ''}>${n}</option>`).join('')}</select><select class="inp" data-in="gf.status" aria-label="Status">${['all', 'Verified', 'Pending', 'Failed'].map(v => `<option value="${v}" ${g.status === v ? 'selected' : ''}>${v === 'all' ? 'All statuses' : v}</option>`).join('')}</select></div>${g.range === 'custom' ? `<div class="inl" style="margin-top:8px"><input class="inp" type="date" data-in="gf.from" value="${g.from}" aria-label="From"><input class="inp" type="date" data-in="gf.to" value="${g.to}" aria-label="To"></div>` : ''}<select class="inp" style="margin-top:8px" data-in="gf.fund" aria-label="Fund"><option value="all">All funds</option>${S.db.funds.map(f => `<option value="${f.id}" ${g.fund === f.id ? 'selected' : ''}>${f.name}</option>`).join('')}</select></div>
<div class="pad"><p class="muted small" style="margin-bottom:6px">${l.length} record${l.length === 1 ? '' : 's'} · Verified total ${money(sum(l.filter(x => x.status === 'Verified')))}</p><div class="card">${shown.length ? shown.map(txRow).join('') : empty('chart', 'No transactions', 'No records match these filters.')}</div>${shown.length < l.length ? `<button class="btn btn-ghost" data-a="more">Load more</button>` : ''}</div>`; };
A.more = () => { UI.gf.page++; render(); };
function filterTx(f) { const now = new Date(); return myTx().filter(x => { const d = new Date(x.date); if (f.range === 'today' && d.toDateString() !== now.toDateString()) return false; if (f.range === 'month' && !sameMonth(d)) return false; if (f.range === 'year' && d.getFullYear() !== now.getFullYear()) return false; if (f.range === 'custom') { if (f.from && d < new Date(f.from)) return false; if (f.to && d > new Date(f.to + 'T23:59:59')) return false; } if (f.fund !== 'all' && x.fund !== f.fund) return false; if (f.status !== 'all' && x.status !== f.status) return false; if (f.q && !(fundName(x.fund) + x.ref + x.method).toLowerCase().includes(f.q.toLowerCase())) return false; return true; }).sort((a, b) => new Date(b.date) - new Date(a.date)); }
A.stmt = () => { const l = filterTx(UI.gf); if (!l.length) return toast('No records to export'); const csv = ['Date,Fund,Amount (' + cur() + '),Method,Reference,Status', ...l.map(x => [fd(x.date), fundName(x.fund), x.amount, x.method, x.ref, x.status].join(','))].join('\n'); dlFile('giving-statement-' + me().code + '.csv', csv + '\n\nDEMO statement – fictional records.', 'text/csv'); toast('Statement downloaded (CSV)'); };
SC.txn = p => { const x = S.db.transactions.find(t => t.id === p.id); if (!x || x.mc !== me().code) return hdr('Transaction') + empty('lock', 'Not available', 'You can only view your own giving records.');
  return hdr('Transaction') + `<div class="pad"><div class="card blue glow" style="text-align:center"><div style="font-size:34px">${fundIcon(x.fund)}</div><div class="small" style="opacity:.8">${fundName(x.fund)}</div><div class="big">${money(x.amount)}</div>${badge(x.status, stClass(x.status))}</div><div class="card">${[['Date & time', fdt(x.date)], ['Payment method', x.method], ['Reference', x.ref], ['Transaction ID', x.id], ['Source', x.source], ['Pledge', x.pledge ? (S.db.pledges.find(p => p.id === x.pledge) || {}).title : '—']].map(([a, b]) => `<div class="row"><span class="muted">${a}</span><b style="margin-left:auto;text-align:right;font-size:13px">${esc(b)}</b></div>`).join('')}</div>${x.status === 'Verified' ? `<button class="btn btn-gold" data-a="receipt" data-id="${x.id}">${ic('dl', 'sm')} Download receipt</button>` : `<div class="notice">⚠️ <span>${x.status === 'Pending' ? 'This record is pending verification and has NOT been received.' : 'This payment did not complete.'} No receipt is available.</span></div>`}</div>`; };
A.receipt = d => { const x = S.db.transactions.find(t => t.id === d.id); dlFile(`receipt-${x.id}.txt`, `${S.db.church.name}\nGIVING RECEIPT (DEMO)\n\nMember: ${me().name} (${me().code})\nFund: ${fundName(x.fund)}\nAmount: ${money(x.amount)}\nDate: ${fdt(x.date)}\nMethod: ${x.method}\nReference: ${x.ref}\nStatus: ${x.status}\n\nFictional demo record.`); toast('Receipt downloaded'); };

/* ============ PLEDGES ============ */
SC.pledges = () => { const l = myPledges(); return hdr('Pledges') + `<div class="pad">${demoNote}${l.length ? l.map(p => { const paid = pledgePaid(p); return `<div class="card tap" data-a="go" data-to="pledge" data-id="${p.id}"><div class="row" style="border:0;padding:0">${ring(pledgePct(p))}<div class="g"><b style="white-space:normal">${esc(p.title)}</b><span class="muted small">Pledged ${money(p.total)}</span><span class="small" style="color:var(--ok);display:block">Paid ${money(paid)}</span><span class="small" style="color:var(--warn)">Remaining ${money(p.total - paid)}</span></div></div></div>`; }).join('') : empty('star', 'No pledges', 'You have no pledge records.')}</div>`; };
SC.pledge = p => { const pl = S.db.pledges.find(x => x.id === p.id); if (!pl || pl.mc !== me().code) return hdr('Pledge') + empty('lock', 'Not available', ''); const paid = pledgePaid(pl), rem = pl.total - paid, pay = S.db.transactions.filter(x => x.pledge === pl.id).sort((a, b) => new Date(b.date) - new Date(a.date));
  const months = Math.max(1, Math.round((new Date(pl.target) - new Date()) / 2592000000)), inst = rem > 0 ? Math.ceil(rem / months / 1000) * 1000 : 0; const sched = []; let left = rem; for (let i = 1; i <= months && left > 0; i++) { const d = new Date(); d.setMonth(d.getMonth() + i); const a = Math.min(inst, left); sched.push([d.toISOString(), a]); left -= a; }
  return hdr('Pledge Details') + `<div class="pad"><div class="card blue glow" style="text-align:center"><div style="display:grid;place-items:center">${ring(pledgePct(pl), 130)}</div><h3 style="margin-top:8px">${esc(pl.title)}</h3><div class="inl" style="margin-top:12px;text-align:center"><div><div class="small" style="opacity:.8">Pledged</div><b>${money(pl.total)}</b></div><div><div class="small" style="opacity:.8">Paid</div><b>${money(paid)}</b></div><div><div class="small" style="opacity:.8">Remaining</div><b>${money(rem)}</b></div></div></div>
<div class="card"><div class="row"><span class="muted">Start</span><b style="margin-left:auto">${fd(pl.start)}</b></div><div class="row"><span class="muted">Target date</span><b style="margin-left:auto">${fd(pl.target)}</b></div><div class="row"><span class="muted">Reminder</span><span style="margin-left:auto">${tog('reminders.' + pl.id, S.reminders[pl.id])}</span></div></div>
<div class="card"><div class="b" style="margin-bottom:6px">Suggested schedule</div>${sched.length ? sched.map(([d, a]) => `<div class="row"><span>${fd(d)}</span><b style="margin-left:auto">${money(a)}</b></div>`).join('') : '<p class="muted">Pledge fully paid 🎉</p>'}</div>
<div class="card"><div class="b" style="margin-bottom:6px">Payments</div>${pay.map(x => `<div class="row tap" data-a="go" data-to="txn" data-id="${x.id}"><div class="g"><b>${money(x.amount)}</b><span class="muted small">${fd(x.date)} · ${x.method}</span></div>${badge(x.status, stClass(x.status))}</div>`).join('') || '<p class="muted">No payments yet.</p>'}</div>
<div class="notice">ⓘ <span>${esc(pl.instr)} Payments are only counted after the church verifies them.</span></div>${rem > 0 ? `<button class="btn btn-gold" data-a="go" data-to="give" data-id="${pl.fund}">Payment instructions</button>` : ''}</div>`; };

/* ============ SERVICES ============ */
const SCATS = ['All', 'Sunday Services', 'Bible Study', 'Youth Services', 'Choir & Worship', 'Conferences'];
SC.services = () => { if (S.settings.offline) return hdr('Online Services', '', false) + errState(); const live = isLive(), l0 = sermonsSorted(), f = l0[0], cat = UI.sCat || 'All', q = (UI.q.ss || '').toLowerCase(); const l = l0.filter(s => (cat === 'All' || s.cat === cat) && (s.title + s.preacher).toLowerCase().includes(q));
  return hdr('Online Services', `<button class="ib" data-a="go" data-to="saved" aria-label="Saved sermons">${ic('bm')}</button>`, false) + `<div class="pad" style="padding-bottom:0"><div class="card blue glow" style="padding:0;overflow:hidden" data-a="go" data-to="sermon" data-id="${f.id}">${art(hash(f.id), '✝️', '', 'height:150px;font-size:60px')}<div style="padding:14px;position:relative;z-index:1">${live ? '<span class="live">LIVE NOW</span>' : '<span class="badge gold">No live broadcast — showing latest</span>'}<h3 style="margin:8px 0 2px">${esc(f.title)}</h3><span class="small" style="opacity:.8">${esc(f.preacher)} · ${fd(f.date)} · ${f.duration}</span></div></div></div>` + search('ss', 'Search sermons or preachers', UI.q.ss) + chips(SCATS.map(c => [c, c]), cat, 'sCat') + `<div class="pad" style="padding-top:0">${S.watched.length ? `<div class="muted small" style="margin-bottom:6px">Recently watched: ${S.watched.slice(0, 3).map(id => esc((S.db.sermons.find(s => s.id === id) || {}).title || '')).join(' · ')}</div>` : ''}${l.length ? l.map(s => `<div class="card tap" data-a="go" data-to="sermon" data-id="${s.id}" style="padding:10px"><div class="row" style="border:0;padding:0"><div style="width:96px;height:64px;border-radius:12px;overflow:hidden;flex:none">${art(hash(s.id), '▶', '', 'height:64px;font-size:20px')}</div><div class="g"><b style="white-space:normal">${esc(s.title)}</b><span class="muted small">${esc(s.preacher)}<br>${fd(s.date)} · ${s.duration}</span></div>${S.saved.includes(s.id) ? '🔖' : ''}</div></div>`).join('') : empty('video', 'No sermons found', 'Try a different search or category.')}</div>`; };
SC.sermon = p => { const s = S.db.sermons.find(x => x.id === p.id); if (!s) return hdr('Sermon') + empty('alert', 'Video unavailable', 'This video is no longer available.'); if (!S.watched.includes(s.id)) { S.watched.unshift(s.id); S.watched = S.watched.slice(0, 10); save(); } const sv = S.saved.includes(s.id);
  return hdr('Sermon', `<button class="ib" data-a="shareSer" data-id="${s.id}" aria-label="Share">${ic('share')}</button>`) + `<div class="pad"><div class="player" style="overflow:hidden;background:#000">${art(hash(s.id), '✝️', '', 'height:190px;font-size:60px')}<button class="play" data-a="playDemo" aria-label="Play">${ic('play', 'lg')}</button></div><h2 style="margin-top:14px">${esc(s.title)}</h2><p class="muted" style="margin:4px 0 10px">${esc(s.preacher)} · ${fd(s.date)} · ${s.duration} · ${s.views} views</p>${badge(s.cat)}<div class="inl" style="margin-top:16px"><button class="btn btn-gold" data-a="openYT" data-id="${s.id}">Open on YouTube</button><button class="btn ${sv ? 'btn-blue' : 'btn-ghost'}" data-a="saveSer" data-id="${s.id}">${sv ? '🔖 Saved' : 'Save'}</button></div><div class="notice" style="margin-top:14px">ⓘ <span>Demo: no real video is attached to this sample sermon. “Open on YouTube” opens the church channel configured in Church Settings.</span></div></div>`; };
A.playDemo = () => toast('Demo player: connect the real YouTube channel/playlist to play videos'); A.openYT = () => window.open(S.db.church.youtube, '_blank', 'noopener');
A.saveSer = d => { const i = S.saved.indexOf(d.id); i < 0 ? S.saved.push(d.id) : S.saved.splice(i, 1); save(); render(); toast(i < 0 ? 'Sermon saved' : 'Removed from saved'); };
A.shareSer = d => { const s = S.db.sermons.find(x => x.id === d.id); share(s.title, `${s.title} — ${s.preacher} · ${S.db.church.youtube}`); };
SC.saved = () => { const l = S.saved.map(id => S.db.sermons.find(s => s.id === id)).filter(Boolean); return hdr('Saved Sermons') + `<div class="pad">${l.length ? l.map(s => `<div class="card tap" data-a="go" data-to="sermon" data-id="${s.id}"><b>${esc(s.title)}</b><div class="muted small">${esc(s.preacher)} · ${s.duration}</div></div>`).join('') : empty('bm', 'Nothing saved yet', 'Save sermons to watch them later.')}</div>`; };

/* ============ COMMUNITY HUB ============ */
SC.community = () => { const items = [['users', 'My Jumuiya', 'Home fellowship', 'jumuiya'], ['heart', 'Prayer Requests', 'Share and track', 'prayer'], ['clock', 'Attendance', 'Check-in & history', 'attendance'], ['book', 'Bible Reading Plans', 'Daily devotional', 'plans'], ['gift', 'Volunteer', 'Serve in ministry', 'volunteer'], ['user', 'Leadership', 'Church directory', 'leadership'], ['file', 'Documents', 'Forms & reports', 'documents'], ['bell', 'Announcements', 'Church news', 'announcements'], ['cal', 'Events', 'RSVP & calendar', 'events'], ['alert', 'Emergency Alerts', 'Urgent notices', 'alerts']]; if (S.db.church.marketplace) items.push(['mkt', 'Marketplace', 'Church-approved services', 'market']);
  return hdr('Community', '', false) + `<div class="pad"><div class="grid2">${items.map(i => `<div class="card tap" style="margin:0" data-a="go" data-to="${i[3]}"><div class="ico gold" style="margin-bottom:10px">${ic(i[0])}</div><b>${i[1]}</b><div class="muted small">${i[2]}</div></div>`).join('')}</div></div>`; };
SC.jumuiya = () => { const g = myGroup(); if (!g) return hdr('My Jumuiya') + empty('lock', 'No Jumuiya registered', 'Private group information is only available to registered members. Contact the church office to join one.'); const tb = UI.jtab, mem = S.db.members.filter(m => m.jumuiya === g.id), pr = S.db.prayers.filter(x => x.privacy === 'Public' && mem.some(m => m.code === x.mc)), isLeader = S.db.jgroles[me().code] === 'Leader';
  const body = tb === 'members' ? `<div class="card">${mem.map(m => `<div class="row"><div class="avatar sm">${initials(m.name)}</div><div class="g"><b>${esc(m.name)}</b><span class="muted small">${S.db.jgroles[m.code] || 'Member'}</span></div>${S.db.jgroles[m.code] === 'Leader' ? `<a class="btn btn-ghost sm" href="tel:${g.phone.replace(/\s/g, '')}">Call</a>` : ''}</div>`).join('')}<p class="muted small" style="margin-top:8px">Only leader contact details are shown. Member phone numbers are private.</p></div>` : tb === 'prayers' ? `<div class="card">${pr.map(x => `<div class="row"><div class="g"><b style="white-space:normal;font-weight:500">${esc(x.text)}</b><span class="muted small">${x.privacy === 'Anonymous' ? 'Anonymous' : esc((S.db.members.find(m => m.code === x.mc) || {}).name)} · ${fd(x.date)}</span></div></div>`).join('') || '<p class="muted">No shared prayer requests.</p>'}</div>` : tb === 'attendance' ? `<div class="card">${[0, 1, 2, 3, 4].map(i => `<div class="row"><span>${fd(nextDow(4, 18, 30).slice(0, 10) && new Date(Date.now() - (i + 1) * 7 * 86400000).toISOString())}</span><span style="margin-left:auto">${badge(i === 2 ? 'Absent' : 'Present', i === 2 ? 'warn' : 'ok')}</span></div>`).join('')}<p class="muted small">Sample attendance (demo).</p></div>` : tb === 'resources' ? `<div class="card">${['Study guide – Week 6.pdf', 'Jumuiya prayer points.pdf', 'Outreach plan.docx'].map(r => `<div class="row"><div class="ico">${ic('file')}</div><div class="g"><b>${r}</b></div><button class="btn btn-ghost sm" data-a="dlGeneric" data-n="${r}.txt">Get</button></div>`).join('')}</div>` : `<div class="card"><div class="row"><div class="ico">${ic('clock')}</div><div class="g"><b>${g.schedule}</b><span class="muted small">Next: ${fd(nextDow(4, 18, 30), { weekday: 'long', day: 'numeric', month: 'short' })}, 6:30 PM</span></div></div><div class="row"><div class="ico">${ic('pin')}</div><div class="g"><b>${esc(g.venue)}</b></div></div><div class="row"><div class="ico">${ic('user')}</div><div class="g"><b>Leader: ${esc(g.leader)}</b><span class="muted small">Assistant: ${esc(g.assistant)}</span></div><a class="btn btn-ghost sm" href="tel:${g.phone.replace(/\s/g, '')}">Call</a></div></div><div class="card"><b>Meeting announcement</b><p class="muted" style="margin-top:6px">This week’s gathering will focus on Romans 8. Please bring your Bible and a friend.</p></div>`;
  return hdr(g.name, `<button class="ib" data-a="go" data-to="chat" aria-label="Group chat">${ic('msg')}</button>`) + art(1, '🏡', '', 'height:120px;font-size:56px') + `<div class="tabs">${[['overview', 'Overview'], ['members', 'Members'], ['prayers', 'Prayers'], ['attendance', 'Attendance'], ['resources', 'Files']].map(([k, l]) => `<button class="${tb === k ? 'on' : ''}" style="font-size:11px" data-a="setui" data-p="jtab" data-v="${k}">${l}</button>`).join('')}</div><div class="pad" style="padding-top:0">${isLeader ? '<div class="badge gold" style="margin-bottom:8px">You are the group leader</div>' : ''}${body}<button class="btn btn-blue" data-a="go" data-to="chat">${ic('msg', 'sm')} Open group chat</button></div>`; };
SC.chat = () => { const g = myGroup(); if (!g) return hdr('Group Chat') + empty('lock', 'Access restricted', 'Only registered Jumuiya members can view this chat.'); setTimeout(() => { const s = $('#screen'); s.scrollTop = s.scrollHeight; }, 30);
  return hdr(g.name + ' · Chat') + `<div class="pad" style="padding-bottom:0"><div class="notice">ⓘ <span>Demo chat stored on this device only. Leaders can moderate messages in production.</span></div></div><div class="chat">${S.db.chat.map(c => `<div class="bub ${c.mc === me().code ? 'me' : ''}">${c.mc !== me().code ? `<div class="nm">${esc(c.from)}</div>` : ''}${esc(c.text)}<small>${ftm(c.date)} ${c.mc === me().code ? '· Sent' : ''}</small></div>`).join('')}</div><form class="compose" data-f="chat"><button type="button" class="ib" data-a="attach" aria-label="Attach">${ic('file')}</button><input name="m" id="cm" placeholder="Message" autocomplete="off" aria-label="Message"><button class="ib btn-gold" style="border-radius:50%" aria-label="Send">${ic('send')}</button></form>`; };
A.attach = () => toast('Attachments are not available in the demo');
FORMS.chat = d => { const m = (d.m || '').trim(); if (!m) return; S.db.chat.push({ id: uid('c'), from: me().name, mc: me().code, text: m, date: new Date().toISOString() }); save(); render(); setTimeout(() => { S.db.chat.push({ id: uid('c'), from: 'Grace Mushi', mc: 'MEM10020', text: 'Amen 🙏 (demo auto-reply)', date: new Date().toISOString() }); save(); if (stack[stack.length - 1].n === 'chat') render(); }, 1500); };

/* ============ DOCUMENTS ============ */
const DCATS = ['All', 'Church Constitution', 'Membership Forms', 'Baptism Forms', 'Wedding Forms', 'Event Programs', 'Annual Reports', 'Financial Reports', 'Bible Study Materials', 'Church Policies', 'Ministry Resources'];
const docIcon = t => ({ PDF: '📕', DOCX: '📘', XLSX: '📗' }[t] || '📄');
SC.documents = () => { const cat = UI.dCat || 'All', q = (UI.q.ds || '').toLowerCase(), l = S.db.documents.filter(d => (cat === 'All' || d.cat === cat) && (d.name + d.desc).toLowerCase().includes(q));
  return hdr('Documents') + search('ds', 'Search documents', UI.q.ds) + chips(DCATS.map(c => [c, c]), cat, 'dCat') + `<div class="pad" style="padding-top:0"><div class="card">${l.length ? l.map(d => `<div class="row tap" data-a="go" data-to="doc" data-id="${d.id}"><div class="ico" style="font-size:22px">${docIcon(d.type)}</div><div class="g"><b>${esc(d.name)}</b><span class="muted small">${d.type} · ${d.size} · ${fd(d.date)}</span></div>${S.downloaded.includes(d.id) ? '✅' : d.restricted === 'Yes' ? '🔒' : ''}</div>`).join('') : empty('file', 'No documents', 'No documents match your search.')}</div></div>`; };
const docAllowed = d => d.restricted !== 'Yes' || isStaff();
SC.doc = p => { const d = S.db.documents.find(x => x.id === p.id); if (!d) return hdr('Document') + empty('alert', 'File unavailable', 'This file has been removed or is not available.'); const ok = docAllowed(d), dl = S.downloaded.includes(d.id), dp = UI.dlProg && UI.dlProg[d.id];
  return hdr('Document Preview', ok ? `<button class="ib" data-a="shareDoc" data-id="${d.id}" aria-label="Share">${ic('share')}</button>` : '') + `<div class="pad"><div class="card" style="text-align:center"><div style="font-size:54px">${docIcon(d.type)}</div><h3>${esc(d.name)}</h3><p class="muted small">${d.type} · ${d.size} · Uploaded ${fd(d.date)}</p>${badge(d.cat)}</div><p class="muted" style="margin-bottom:12px">${esc(d.desc)}</p>${!ok ? `<div class="notice" style="background:rgba(217,48,37,.12);color:var(--err)">🔒 <span>You don’t have permission to access this document. Access is checked before download.</span></div>` : `${dl || !S.settings.offline ? `<div class="pre">${esc(d.name)}\n\n${esc(d.desc)}\n\n[Demo preview] This is placeholder text. In production the real ${d.type} file is fetched from Firebase Storage after a permission check.</div>` : errState('refresh')}<div style="height:12px"></div>${dp !== undefined ? `<div class="bar"><i style="width:${dp}%"></i></div><p class="muted small" style="margin-top:4px">Downloading… ${dp}%</p>` : `<button class="btn ${dl ? 'btn-ghost' : 'btn-gold'}" data-a="dlDoc" data-id="${d.id}">${ic('dl', 'sm')} ${dl ? 'Downloaded — available offline (tap to save copy)' : 'Download'}</button>`}`}</div>`; };
A.dlDoc = d => { const doc = S.db.documents.find(x => x.id === d.id); if (!docAllowed(doc)) return toast('Access denied'); if (S.downloaded.includes(d.id)) { dlFile(doc.name + '.txt', `${doc.name}\n\nDemo placeholder document.`); return; } if (S.settings.offline) return toast('No connection (simulated). Turn off “Simulate offline” in Settings.'); UI.dlProg = UI.dlProg || {}; UI.dlProg[d.id] = 0; const iv = setInterval(() => { UI.dlProg[d.id] += 20; if (UI.dlProg[d.id] >= 100) { clearInterval(iv); delete UI.dlProg[d.id]; S.downloaded.push(d.id); save(); dlFile(doc.name + '.txt', `${doc.name}\n\nDemo placeholder document.`); toast('Downloaded for offline access'); } if (stack[stack.length - 1].n === 'doc') render(); }, 250); render(); };
A.shareDoc = d => { const x = S.db.documents.find(y => y.id === d.id); share(x.name, x.desc); };

/* ============ LEADERSHIP ============ */
const LGROUPS = ['Senior Pastor', 'Assistant Pastors', 'Elders', 'Deacons', 'Church Administrator', 'Youth Leaders', 'Women\'s Ministry', 'Men\'s Ministry', 'Choir Leaders', 'Jumuiya Leaders', 'Department Leaders'];
SC.leadership = () => { const q = (UI.q.ls || '').toLowerCase(), l = S.db.leaders.filter(x => (x.name + x.position + x.ministry).toLowerCase().includes(q));
  return hdr('Leadership Directory') + search('ls', 'Search leaders', UI.q.ls) + `<div class="pad" style="padding-top:0">${LGROUPS.map(g => { const m = l.filter(x => x.group === g); return m.length ? `<div class="muted small b" style="margin:10px 0 6px;text-transform:uppercase;letter-spacing:.6px">${g}</div><div class="card">${m.map(x => `<div class="row tap" data-a="go" data-to="leader" data-id="${x.id}"><div class="avatar">${initials(x.name)}</div><div class="g"><b>${esc(x.name)}</b><span class="muted small">${esc(x.position)}</span></div>${ic('chev')}</div>`).join('')}</div>` : ''; }).join('') || empty('users', 'No leaders found', '')}</div>`; };
SC.leader = p => { const x = S.db.leaders.find(l => l.id === p.id); if (!x) return hdr('Leader') + empty('alert', 'Not found', ''); const tel = x.phone.replace(/\s/g, '');
  return hdr('Leader Details') + `<div class="pad" style="text-align:center"><div class="avatar lg" style="margin:0 auto 10px">${initials(x.name)}</div><h2>${esc(x.name)}</h2><p class="muted">${esc(x.position)} · ${esc(x.ministry)}</p><div class="card" style="text-align:left;margin-top:16px"><div class="row"><div class="ico">${ic('clock')}</div><div class="g"><b>Office hours</b><span class="muted small">${esc(x.hours)}</span></div></div><div class="row"><div class="ico">${ic('phone')}</div><div class="g"><b>${esc(x.phone)}</b><span class="muted small">Official church number</span></div></div><div class="row"><div class="ico">${ic('mail')}</div><div class="g"><b style="font-size:13px">${esc(x.email)}</b></div></div></div><div class="inl"><a class="btn btn-gold" href="tel:${tel}">${ic('phone', 'sm')} Call</a><a class="btn btn-blue" href="mailto:${x.email}">${ic('mail', 'sm')} Email</a></div></div>`; };

/* ============ NOTIFICATIONS / ALERTS ============ */
const NIC = { announcements: 'bell', events: 'cal', live: 'video', jumuiya: 'users', giving: 'heart', admin: 'shield' };
SC.notifications = () => { const l = S.db.notifications.filter(n => S.settings.notif[n.type] !== false).sort((a, b) => new Date(b.date) - new Date(a.date)), un = l.filter(n => !n.read).length;
  return hdr('Notifications', `<button class="ib" data-a="go" data-to="notifPrefs" aria-label="Preferences">${ic('sliders')}</button>`) + `<div class="pad"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px"><b>${un} unread</b><button class="btn btn-ghost sm" data-a="readAll">Mark all as read</button></div><div class="card">${l.length ? l.map(n => `<div class="row tap" data-a="readN" data-id="${n.id}"><div class="ico ${n.read ? '' : 'gold'}">${ic(NIC[n.type] || 'bell')}</div><div class="g"><b style="white-space:normal;${n.read ? 'font-weight:500' : ''}">${esc(n.title)}</b><span class="muted small" style="white-space:normal;display:block">${esc(n.body)}</span><span class="muted small">${fdt(n.date)}</span></div>${n.read ? '' : '<span style="color:var(--gold)">●</span>'}</div>`).join('') : empty('bell', 'No notifications', 'You’re all caught up.')}</div><p class="muted small" style="text-align:center">Giving notifications never show amounts on the lock screen.</p></div>`; };
A.readN = d => { const n = S.db.notifications.find(x => x.id === d.id); n.read = !n.read; save(); render(); }; A.readAll = () => { S.db.notifications.forEach(n => n.read = true); save(); render(); toast('All marked as read'); };
SC.notifPrefs = () => hdr('Notification Preferences') + `<div class="pad"><div class="card">${[['announcements', 'Announcements'], ['events', 'Event reminders'], ['live', 'Livestream & sermons'], ['jumuiya', 'Jumuiya updates'], ['giving', 'Giving reminders'], ['admin', 'Church messages']].map(([k, l]) => `<div class="row"><b style="font-weight:500">${l}</b><span style="margin-left:auto">${tog('settings.notif.' + k, S.settings.notif[k])}</span></div>`).join('')}</div><p class="muted small">Production push notifications use Firebase Cloud Messaging (not active in demo).</p></div>`;
SC.alerts = () => hdr('Emergency Alerts') + `<div class="pad">${S.db.alerts.length ? S.db.alerts.map(a => { const ack = S.alertAck.includes(a.id); return `<div class="card" style="border-left:5px solid var(--err)"><span class="badge err">${a.priority.toUpperCase()} PRIORITY</span><h3 style="margin:8px 0">${esc(a.title)}</h3><p style="line-height:1.5">${esc(a.body)}</p><p class="muted small" style="margin:8px 0">Issued by ${esc(a.issuer)} · ${fdt(a.date)}</p>${a.required ? `<button class="btn ${ack ? 'btn-ghost' : 'btn-red'}" data-a="ack" data-id="${a.id}">${ack ? '✓ Read confirmed' : 'Confirm I have read this'}</button>` : ''}</div>`; }).join('') : empty('shield', 'No active alerts', 'Urgent church notices appear here.')}</div>`;
A.ack = d => { if (!S.alertAck.includes(d.id)) S.alertAck.push(d.id); save(); render(); toast('Read confirmation recorded'); };
SC.market = () => hdr('Marketplace') + `<div class="pad"><div class="notice">ⓘ <span>Optional module. Listings are church-approved. No payments are processed.</span></div>${S.db.market.map(m => `<div class="card"><b>${esc(m.name)}</b><p class="muted small" style="margin:4px 0">${esc(m.desc)}</p>${badge('Contact: ' + m.contact)}</div>`).join('')}</div>`;

/* ============ PROFILE ============ */
SC.profile = () => { const m = me(), g = S.db.groups.find(x => x.id === m.jumuiya);
  const L = (i, l, to, extra = '') => `<div class="row tap" data-a="go" data-to="${to}"><div class="ico">${ic(i)}</div><div class="g"><b>${l}</b></div>${extra}${ic('chev')}</div>`;
  return `<div class="hero" style="text-align:center;padding-bottom:60px"><div class="avatar lg" style="margin:0 auto 8px">${initials(m.name)}</div><h2>${esc(m.name)}</h2><small>${m.code} · ${esc(S.db.church.name)}</small><div style="margin-top:8px">${badge(m.status, stClass(m.status))} ${isStaff() ? badge(ROLES[myRole()].label, 'gold') : ''}</div></div><div class="up"><div class="card">${[['Member since', fd(m.joined)], ['Phone', m.phone], ['Email', m.email], ['Jumuiya', g ? g.name : '—'], ['Ministries', (m.ministries || []).join(', ') || '—']].map(([a, b]) => `<div class="row"><span class="muted">${a}</span><b style="margin-left:auto;text-align:right;font-size:13px">${esc(b)}</b></div>`).join('')}</div><div class="card">${L('edit', 'Edit Profile', 'editProfile')}${L('qr', 'Digital Membership Card', 'card')}${L('heart', 'Prayer Requests', 'prayer')}${L('book', 'Bible Reading Plans', 'plans')}${L('gift', 'Volunteer Registration', 'volunteer')}${L('bell', 'Notifications', 'notifications')}${L('cog', 'Settings', 'settings')}${L('shield', 'Privacy', 'privacy')}${L('help', 'Help & Support', 'help')}${isStaff() ? L('chart', 'Admin Dashboard', 'admin') : ''}</div><button class="btn btn-red" data-a="logout">${ic('logout', 'sm')} Log out</button></div><div style="height:16px"></div>`; };
A.logout = () => confirmBox('Log out of this demo account?', () => { S.session = null; save(); reset('login'); toast('Logged out'); }, 'Log out');
SC.editProfile = () => { const m = me(); return hdr('Edit Profile') + `<div class="pad"><div class="notice">ⓘ Only approved fields can be edited. Name and member code are managed by the church office.</div><form data-f="profile"><label class="lbl" for="ep">Phone</label><input class="inp" id="ep" name="phone" value="${esc(m.phone)}" required><label class="lbl" for="ee">Email</label><input class="inp" id="ee" name="email" type="email" value="${esc(m.email)}" required><label class="lbl" for="ea">Address</label><input class="inp" id="ea" name="address" value="${esc(m.address || '')}"><div style="height:16px"></div><button class="btn btn-gold">Save changes</button></form></div>`; };
FORMS.profile = d => { if (!/^\+?[\d\s]{7,16}$/.test(d.phone)) return toast('Enter a valid phone number'); Object.assign(me(), { phone: d.phone, email: d.email, address: d.address }); save(); back(); toast('Profile updated'); };
SC.card = () => { const m = me(), tok = 'tok-' + Math.abs(hash(m.code + 'salt')).toString(36);
  return hdr('Membership Card') + `<div class="pad"><div class="mc"><div style="display:flex;justify-content:space-between;align-items:center"><div>${LOGO(46)}</div><div style="text-align:right"><b>${esc(S.db.church.name)}</b><div class="small" style="opacity:.8">Member Card</div></div></div><div style="margin:20px 0 4px;font-size:22px;font-weight:700">${esc(m.name)}</div><div style="opacity:.85;letter-spacing:2px">${m.code}</div><div style="display:flex;justify-content:space-between;align-items:flex-end;margin-top:16px"><div>${badge(m.status, 'ok')}<div class="small" style="opacity:.8;margin-top:6px">Since ${fd(m.joined, { month: 'short', year: 'numeric' })}</div></div><div style="background:#fff;padding:6px;border-radius:12px">${qrSvg(tok)}</div></div></div><div class="notice" style="margin-top:14px">ⓘ <span>The QR contains only a revocable verification token (<code>${tok}</code>), never personal data. In this demo it is a decorative placeholder and not scannable.</span></div></div>`; };

/* ============ SETTINGS ============ */
SC.settings = () => { const st = S.settings; return hdr('Settings') + `<div class="pad"><div class="card"><div class="row"><b style="font-weight:500">Dark mode</b><span style="margin-left:auto">${tog('settings.themeDark', st.theme === 'dark')}</span></div><div class="row"><b style="font-weight:500">Language</b><select class="inp" style="width:auto;margin-left:auto" data-set="settings.lang"><option value="en" ${st.lang === 'en' ? 'selected' : ''}>English</option><option value="sw" ${st.lang === 'sw' ? 'selected' : ''}>Kiswahili</option></select></div><div class="row tap" data-a="go" data-to="notifPrefs"><b style="font-weight:500">Notification preferences</b>${ic('chev')}</div></div>
<div class="card"><div class="b" style="margin-bottom:4px">Security</div><div class="row tap" data-a="chPw"><b style="font-weight:500">Change password</b>${ic('chev')}</div><div class="row"><b style="font-weight:500">Biometric unlock (simulated)</b><span style="margin-left:auto">${tog('settings.biometric', st.biometric)}</span></div><div class="row"><b style="font-weight:500">Remember this device</b><span style="margin-left:auto">${tog('settings.remember', st.remember)}</span></div></div>
<div class="card"><div class="b" style="margin-bottom:4px">Downloads & data</div><div class="row"><b style="font-weight:500">Download on Wi-Fi only</b><span style="margin-left:auto">${tog('settings.wifiOnly', st.wifiOnly)}</span></div><div class="row"><b style="font-weight:500">Simulate offline mode</b><span style="margin-left:auto">${tog('settings.offline', st.offline)}</span></div><div class="row tap" data-a="clearCache"><b style="font-weight:500">Clear downloaded files & cache</b>${ic('chev')}</div></div>
<div class="card"><div class="row tap" data-a="go" data-to="privacy"><b style="font-weight:500">Privacy information</b>${ic('chev')}</div><div class="row tap" data-a="go" data-to="help"><b style="font-weight:500">Contact support</b>${ic('chev')}</div><div class="row tap" data-a="about"><b style="font-weight:500">About this app</b>${ic('chev')}</div></div>
<div class="card"><div class="b" style="margin-bottom:4px">Demo data</div><button class="btn btn-ghost" data-a="resetDemo">Reset demonstration dataset</button></div><button class="btn btn-red" data-a="logout">Log out</button></div>`; };
const _tog = A.tog; A.tog = d => { if (d.k === 'settings.themeDark') { S.settings.theme = S.settings.theme === 'dark' ? 'light' : 'dark'; save(); return render(); } _tog(d); };
A.clearCache = () => { S.downloaded = []; save(); toast('Downloaded files cleared'); render(); };
A.about = () => sheet(`<h3>Faith Community Church App</h3><p class="muted">Browser demo v1.0 · Demo mode<br>All records are fictional and stored only in this browser.</p>`);
A.resetDemo = () => confirmBox('This restores all sample data and clears your demo changes.', () => { localStorage.removeItem(LS); S = fresh(); save(); UI.seen = {}; reset('login'); toast('Demo data reset'); }, 'Reset');
A.chPw = () => sheet(`<h3>Change password</h3><form data-f="chpw"><label class="lbl">Current password</label><input class="inp" name="cur" type="password" required><label class="lbl">New password (min 8)</label><input class="inp" name="np" type="password" required><div style="height:14px"></div><button class="btn btn-gold">Update</button></form>`);
FORMS.chpw = d => { const c = S.creds.find(x => x.code === S.session.code); if (!c || c.pw !== d.cur) return toast('Current password is incorrect'); if (d.np.length < 8) return toast('Minimum 8 characters'); c.pw = d.np; save(); closeSheet(); toast('Password changed (demo)'); };
SC.privacy = () => hdr('Privacy Information') + `<div class="pad"><div class="card" style="line-height:1.6"><b>How your information is handled</b><ul style="margin:8px 0 0 18px;font-size:14px"><li>You can only see your own giving and pledge records.</li><li>Private prayer requests are visible only to authorised pastoral staff.</li><li>Group chats and member lists are visible only to registered group members.</li><li>Leader contact details shown are official, church-approved numbers.</li><li>Your QR membership code holds a revocable token, not personal data.</li><li>Roles and permissions are enforced by the server in production, never by this app.</li></ul></div><p class="muted small">This demo stores sample data locally in your browser only.</p></div>`;
SC.help = () => hdr('Help & Support') + `<div class="pad"><div class="card">${[['How do I RSVP to an event?', 'Open Events, choose an event and tap RSVP. You can cancel the same way.'], ['Why is my contribution Pending?', 'Contributions are counted only after the church verifies them. Pending records are not counted as received.'], ['How do I download a statement?', 'Giving → History → tap the download icon. Filters apply to the export.'], ['I forgot my password', 'Use “Forgot Password” on the login page or contact the church administrator.']].map(([q, a]) => `<div style="margin-bottom:12px"><b>${q}</b><p class="muted small">${a}</p></div>`).join('')}</div><div class="inl"><a class="btn btn-gold" href="tel:${S.db.church.phone.replace(/\s/g, '')}">Call office</a><a class="btn btn-blue" href="mailto:${S.db.church.email}">Email</a></div></div>`;

/* ============ PRAYER ============ */
SC.prayer = () => { const l = S.db.prayers.filter(x => x.mc === me().code).sort((a, b) => new Date(b.date) - new Date(a.date)); return hdr('Prayer Requests', `<button class="ib" data-a="go" data-to="prayerNew" aria-label="New request">${ic('plus')}</button>`) + `<div class="pad">${l.length ? l.map(x => `<div class="card"><div style="display:flex;gap:6px;margin-bottom:6px">${badge(x.privacy === 'Confidential' ? '🔒 Confidential' : x.privacy, x.privacy === 'Confidential' ? 'err' : '')}${badge(x.status, 'gold')}</div><p>${esc(x.text)}</p><div class="muted small" style="margin-top:6px">${fd(x.date)}</div>${x.status !== 'Answered' && x.status !== 'Withdrawn' ? `<button class="btn btn-ghost sm" style="margin-top:8px" data-a="withdraw" data-id="${x.id}">Withdraw</button>` : ''}</div>`).join('') : empty('heart', 'No prayer requests', 'Submit a request and the church will pray with you.')}<button class="btn btn-gold" data-a="go" data-to="prayerNew">Submit a prayer request</button></div>`; };
SC.prayerNew = () => hdr('New Prayer Request') + `<div class="pad"><div class="notice">ⓘ Confidential requests are visible only to authorised pastoral staff. Demo submission saved on this device.</div><form data-f="prayer"><label class="lbl" for="pt">Your request</label><textarea class="inp" id="pt" name="text" required maxlength="500"></textarea><label class="check"><input type="checkbox" name="anon"> Hide my name (anonymous)</label><label class="check"><input type="checkbox" name="conf"> Request confidential pastoral support</label><button class="btn btn-gold">Submit request</button></form></div>`;
FORMS.prayer = d => { if (!d.text.trim()) return toast('Please write your request'); S.db.prayers.unshift({ id: uid('pr'), mc: me().code, text: d.text.trim(), privacy: d.conf ? 'Confidential' : d.anon ? 'Anonymous' : 'Public', status: 'Received', date: new Date().toISOString() }); save(); back(); toast('Prayer request submitted (demo)'); };
A.withdraw = d => confirmBox('Withdraw this request?', () => { S.db.prayers.find(x => x.id === d.id).status = 'Withdrawn'; save(); render(); }, 'Withdraw');

/* ============ ATTENDANCE ============ */
SC.attendance = () => { const rec = S.db.attendance.concat(S.checkins).sort((a, b) => new Date(b.date) - new Date(a.date)), pr = rec.filter(r => r.status === 'Present').length, ck = S.db.checkin;
  const ups = [0, 1].map(i => ({ date: nextDow(0, 8, 0), service: 'Sunday Worship Service' })); ups[1].date = new Date(new Date(ups[0].date).getTime() + 7 * 86400000).toISOString();
  return hdr('Attendance') + `<div class="pad"><div class="grid2"><div class="card blue" style="margin:0"><div class="small" style="opacity:.8">Attended</div><div class="big">${pr}/${rec.length}</div></div><div class="card" style="margin:0"><div class="small muted">Attendance rate</div><div class="big">${rec.length ? Math.round(pr / rec.length * 100) : 0}%</div></div></div><div class="sec" style="margin:16px 0 8px"><span>QR / code check-in</span></div><div class="card">${ck.open ? `<p style="margin-bottom:8px"><b>${esc(ck.service)}</b> check-in is open.</p><form data-f="checkin"><input class="inp" name="code" placeholder="Enter service code" required><div style="height:10px"></div><button class="btn btn-blue">${ic('qr', 'sm')} Check in</button></form>` : `<p class="muted">Check-in is not open right now. It opens during services when the church enables it.</p>`}<p class="muted small" style="margin-top:8px">Codes are validated by the church server in production, not by this app.</p></div><div class="sec" style="margin:16px 0 8px"><span>Upcoming services</span></div><div class="card">${ups.map(u => `<div class="row"><div class="ico">${ic('cal')}</div><div class="g"><b>${u.service}</b><span class="muted small">${fd(u.date, { weekday: 'long', day: 'numeric', month: 'short' })} · ${ftm(u.date)}</span></div></div>`).join('')}</div><div class="sec" style="margin:16px 0 8px"><span>History</span></div><div class="card">${rec.map(r => `<div class="row"><div class="g"><b>${esc(r.service)}</b><span class="muted small">${fd(r.date)}</span></div>${badge(r.status, r.status === 'Present' ? 'ok' : 'warn')}</div>`).join('')}</div></div>`; };
FORMS.checkin = d => { const ck = S.db.checkin; if (!ck.open || d.code.trim().toUpperCase() !== ck.code) return toast('Invalid or expired check-in code'); if (S.checkins.some(c => c.service === ck.service && fd(c.date) === fd(new Date().toISOString()))) return toast('You are already checked in'); S.checkins.push({ date: new Date().toISOString(), service: ck.service, status: 'Present' }); save(); render(); toast('✓ Check-in confirmed'); };

/* ============ DEVOTIONALS ============ */
SC.plans = () => hdr('Bible Reading Plans', `<button class="ib" data-a="go" data-to="devotional" aria-label="Daily devotional">${ic('book')}</button>`) + `<div class="pad"><div class="card scr tap" data-a="go" data-to="devotional"><small style="color:#F5CF65">TODAY’S DEVOTIONAL</small><h3 style="margin:6px 0">${verseOfDay().ref}</h3><span class="small" style="opacity:.85">Tap to read</span></div>${S.db.plans.map(p => { const done = (S.plans[p.id] || []).length; return `<div class="card tap" data-a="go" data-to="plan" data-id="${p.id}"><b>${p.title}</b><p class="muted small" style="margin:4px 0 8px">${p.desc}</p><div class="bar"><i style="width:${done / p.days * 100}%"></i></div><div class="muted small" style="margin-top:4px">${done}/${p.days} days complete</div></div>`; }).join('')}<div class="sec" style="margin:14px 0 8px"><span>Saved verses</span></div>${S.verses.length ? S.verses.map(r => { const v = VERSES.find(x => x.ref === r); return `<div class="card"><b>${v.ref}</b><p class="muted small">${esc(v.text)}</p></div>`; }).join('') : '<p class="muted small">Save verses from the daily devotional.</p>'}</div>`;
const reading = (p, i) => p.list ? p.list[i] : `${p.book} ${i + 1}`;
SC.plan = q => { const p = S.db.plans.find(x => x.id === q.id), done = S.plans[p.id] || [];
  return hdr(p.title) + `<div class="pad"><div class="card"><div class="bar"><i style="width:${done.length / p.days * 100}%"></i></div><p class="muted small" style="margin-top:6px">${done.length}/${p.days} complete${done.length === p.days ? ' 🎉' : ''}</p><div class="row"><b style="font-weight:500">Daily reminder</b><span style="margin-left:auto">${tog('reminders.' + p.id, S.reminders[p.id])}</span></div></div><div class="card">${Array.from({ length: p.days }, (_, i) => `<div class="row tap" data-a="planDay" data-id="${p.id}" data-i="${i}"><div class="ico ${done.includes(i) ? 'gold' : ''}">${done.includes(i) ? ic('check') : i + 1}</div><div class="g"><b>Day ${i + 1}</b><span class="muted small">${reading(p, i)}</span></div></div>`).join('')}</div></div>`; };
A.planDay = d => { const a = S.plans[d.id] = S.plans[d.id] || [], i = +d.i, k = a.indexOf(i); k < 0 ? a.push(i) : a.splice(k, 1); save(); render(); };
SC.devotional = () => { const v = verseOfDay(), sv = S.verses.includes(v.ref); return hdr('Daily Devotional') + `<div class="pad"><div class="scr"><small style="color:#F5CF65;font-weight:700">${fd(new Date().toISOString(), { weekday: 'long', day: 'numeric', month: 'long' })}</small><h2 style="margin:6px 0">${v.ref}</h2><q>${esc(v.text)}</q><small style="opacity:.7;display:block;margin-top:8px">King James Version (public domain)</small></div><div class="card" style="margin-top:14px"><b>Reflection</b><p style="margin-top:6px;line-height:1.6">${esc(v.note)}</p></div><div class="inl"><button class="btn ${sv ? 'btn-blue' : 'btn-ghost'}" data-a="saveVerse" data-r="${v.ref}">${sv ? '🔖 Saved' : 'Save verse'}</button><button class="btn btn-gold" data-a="shareVerse" data-r="${v.ref}">Share card</button></div></div>`; };
A.saveVerse = d => { const i = S.verses.indexOf(d.r); i < 0 ? S.verses.push(d.r) : S.verses.splice(i, 1); save(); render(); };

/* ============ VOLUNTEER ============ */
SC.volunteer = () => { const apps = S.applications.filter(a => a.mc === me().code); return hdr('Volunteer Registration') + `<div class="pad">${apps.length ? `<div class="b" style="margin-bottom:6px">My applications</div><div class="card">${apps.map(a => `<div class="row"><div class="g"><b>${esc((S.db.opps.find(o => o.id === a.opp) || {}).name)}</b><span class="muted small">${fd(a.date)}</span></div>${badge(a.status, stClass(a.status) || 'warn')}</div>`).join('')}</div>` : ''}<div class="b" style="margin:8px 0">Opportunities</div>${S.db.opps.map(o => `<div class="card tap" data-a="oppSheet" data-id="${o.id}"><div class="row" style="border:0;padding:0"><div class="ico gold">${ic('gift')}</div><div class="g"><b>${esc(o.name)}</b><span class="muted small" style="white-space:normal">${esc(o.desc)}</span></div>${ic('chev')}</div></div>`).join('')}</div>`; };
A.oppSheet = d => { const o = S.db.opps.find(x => x.id === d.id), ap = S.applications.find(a => a.opp === o.id && a.mc === me().code); sheet(`<h3>${esc(o.name)}</h3><p style="margin:6px 0">${esc(o.desc)}</p><p class="muted small"><b>Requirements:</b> ${esc(o.requirements)}<br><b>Coordinator:</b> ${esc(o.coordinator)} · ${o.slots} spots</p>${ap ? `<div style="margin-top:12px">${badge('Application: ' + ap.status, 'warn')}</div>` : `<form data-f="apply" style="margin-top:12px"><input type="hidden" name="opp" value="${o.id}"><label class="lbl">Why would you like to serve?</label><textarea class="inp" name="msg" required></textarea><div style="height:12px"></div><button class="btn btn-gold">Submit application</button></form><p class="muted small" style="margin-top:8px">Visible only to the ministry coordinator.</p>`}`); };
FORMS.apply = d => { S.applications.push({ id: uid('ap'), mc: me().code, opp: d.opp, msg: d.msg, status: 'Pending', date: new Date().toISOString() }); save(); closeSheet(); render(); toast('Application submitted (demo)'); };

/* ============ ADMIN ============ */
const F = (k, l, t = 't', o) => ({ k, l, t, o });
const MOD = {
  members: { t: 'Member Management', perm: 'members', col: 'members', ti: r => r.name, su: r => `${r.code} · ${r.status}`, f: [F('name', 'Full name'), F('code', 'Member code'), F('phone', 'Phone'), F('email', 'Email'), F('status', 'Status', 's', ['Active', 'Inactive', 'Suspended']), F('jumuiya', 'Jumuiya ID (g1–g4)')], blank: { status: 'Active', joined: new Date().toISOString(), ministries: [], address: '' } },
  announcements: { t: 'Announcements', perm: 'announcements', col: 'announcements', ti: r => r.title, su: r => `${r.status} · ${r.cat} · ${fd(r.date)}`, f: [F('title', 'Title'), F('cat', 'Category', 's', ['Important', 'Events', 'Ministry', 'General']), F('priority', 'Priority', 's', ['Low', 'Normal', 'High']), F('body', 'Message', 'a'), F('date', 'Publish date', 'd'), F('status', 'Status', 's', ['Published', 'Scheduled', 'Archived'])], blank: { cat: 'General', priority: 'Normal', status: 'Published', img: '📢', attach: false, date: new Date().toISOString() } },
  events: { t: 'Events', perm: 'events', col: 'events', ti: r => r.title, su: r => `${r.cat} · ${fd(r.start)}`, f: [F('title', 'Title'), F('cat', 'Category', 's', EVCATS.slice(1)), F('start', 'Start', 'd'), F('end', 'End', 'd'), F('venue', 'Venue'), F('desc', 'Description', 'a'), F('organizer', 'Organizer contact'), F('cap', 'Capacity', 'n')], blank: { img: '🎟️', baseReg: 0, cat: 'Sunday Services', cap: 100, start: new Date().toISOString(), end: new Date(Date.now() + 7200000).toISOString() } },
  leadership: { t: 'Leadership', perm: 'leadership', col: 'leaders', ti: r => r.name, su: r => r.position, f: [F('name', 'Name'), F('position', 'Position'), F('group', 'Group', 's', LGROUPS), F('ministry', 'Ministry'), F('phone', 'Church phone'), F('email', 'Official email'), F('hours', 'Office hours')], blank: { group: 'Department Leaders' } },
  groups: { t: 'Jumuiya', perm: 'groups', col: 'groups', ti: r => r.name, su: r => `Leader: ${r.leader}`, f: [F('name', 'Name'), F('leader', 'Leader'), F('assistant', 'Assistant'), F('venue', 'Venue'), F('schedule', 'Schedule'), F('phone', 'Leader phone')], blank: {} },
  sermons: { t: 'Sermons & YouTube', perm: 'sermons', col: 'sermons', ti: r => r.title, su: r => `${r.preacher} · ${fd(r.date)}`, f: [F('title', 'Title'), F('preacher', 'Preacher'), F('cat', 'Category', 's', SCATS.slice(1)), F('date', 'Date', 'd'), F('duration', 'Duration (mm:ss)'), F('ytId', 'YouTube video ID')], blank: { views: 0, cat: 'Sunday Services', date: new Date().toISOString() } },
  documents: { t: 'Documents', perm: 'documents', col: 'documents', ti: r => r.name, su: r => `${r.cat} · ${r.type}${r.restricted === 'Yes' ? ' · 🔒' : ''}`, f: [F('name', 'File name'), F('cat', 'Category', 's', DCATS.slice(1)), F('type', 'Type', 's', ['PDF', 'DOCX', 'XLSX']), F('size', 'Size'), F('desc', 'Description', 'a'), F('restricted', 'Restricted?', 's', ['No', 'Yes'])], blank: { type: 'PDF', size: '1 MB', restricted: 'No', date: new Date().toISOString(), cat: 'Ministry Resources' } },
  opps: { t: 'Volunteer Opportunities', perm: 'volunteers', col: 'opps', ti: r => r.name, su: r => `${r.coordinator} · ${r.slots} spots`, f: [F('name', 'Ministry'), F('desc', 'Description', 'a'), F('requirements', 'Requirements', 'a'), F('coordinator', 'Coordinator'), F('slots', 'Open spots', 'n')], blank: { slots: 5 } },
  alerts: { t: 'Emergency Alerts', perm: 'alerts', col: 'alerts', ti: r => r.title, su: r => `${r.priority} · ${fdt(r.date)}`, f: [F('title', 'Title'), F('body', 'Alert message', 'a'), F('priority', 'Priority', 's', ['High', 'Critical']), F('issuer', 'Issuing authority')], blank: { priority: 'High', required: true, date: new Date().toISOString() } }
};
const ADM = [['members', 'users', 'Members'], ['announcements', 'bell', 'Announcements'], ['events', 'cal', 'Events'], ['giving', 'heart', 'Giving Records'], ['pledges', 'star', 'Pledges'], ['documents', 'file', 'Documents'], ['leadership', 'user', 'Leadership'], ['groups', 'users', 'Jumuiya'], ['sermons', 'video', 'Sermons / YouTube'], ['notifs', 'send', 'Notifications'], ['prayers', 'heart', 'Prayer Requests'], ['attendance', 'clock', 'Attendance'], ['opps', 'gift', 'Volunteers'], ['alerts', 'alert', 'Emergency Alerts'], ['roles', 'shield', 'Roles & Permissions'], ['reports', 'chart', 'Reports & Analytics'], ['audit', 'file', 'Audit Logs'], ['settings', 'cog', 'Church Settings']];
const permOf = k => ({ notifs: 'notifications', opps: 'volunteers', roles: 'roles' }[k] || k);
const guard = k => can(permOf(k)) ? null : hdr('Access denied') + empty('lock', 'Not authorised', 'Your role does not include this module. Permissions are enforced by the server in production.');
SC.admin = () => { if (!isStaff()) return hdr('Admin') + empty('lock', 'Not authorised', 'Administrator access required.');
  const d = S.db, ps = d.pledges.reduce((a, p) => a + p.total - pledgePaid(p), 0), cards = [['Registered members', d.members.length], ['Active members', d.members.filter(m => m.status === 'Active').length], ['Last Sunday attendance', d.agg.attendance.at(-1)], ['Events', d.events.length], ['Announcements', d.announcements.length], ['Giving records', d.transactions.length], ['Outstanding pledges', money(ps)], ['Documents', d.documents.length]];
  return hdr('Admin Dashboard', badge(ROLES[myRole()].label, 'gold')) + `<div class="pad"><div class="notice">ⓘ <span>Demo admin. Roles here are simulated; in production the server enforces permissions and the audit log. Analytics are sample data.</span></div><div class="grid2">${cards.map(c => `<div class="card" style="margin:0"><div class="muted small">${c[0]}</div><div class="b" style="font-size:20px;margin-top:4px">${c[1]}</div></div>`).join('')}</div><div class="card" style="margin-top:14px"><div class="b" style="margin-bottom:6px">Attendance over time</div>${lineChart(d.agg.months, d.agg.attendance)}</div><div class="sec" style="margin:14px 0 8px"><span>Modules</span></div><div class="grid2">${ADM.filter(m => can(permOf(m[0]))).map(m => `<div class="card tap" style="margin:0;padding:12px" data-a="go" data-to="adm" data-id="${m[0]}"><div class="ico" style="margin-bottom:6px">${ic(m[1])}</div><b style="font-size:13px">${m[2]}</b></div>`).join('')}</div></div>`; };
SC.adm = p => { const k = p.id, g = guard(k); if (g) return g; const lab = ADM.find(m => m[0] === k)[2]; const fn = ADMS[k]; if (fn) return hdr(lab) + fn(); return crud(k); };
function crud(k) { const m = MOD[k], q = (UI.q['ad' + k] || '').toLowerCase(), l = S.db[m.col].filter(r => (m.ti(r) + m.su(r)).toLowerCase().includes(q));
  return hdr(m.t, `<button class="ib" data-a="admNew" data-k="${k}" aria-label="Add">${ic('plus')}</button>`) + search('ad' + k, 'Search', UI.q['ad' + k]) + `<div class="pad" style="padding-top:0"><div class="card">${l.map(r => `<div class="row tap" data-a="admEdit" data-k="${k}" data-id="${r.id}"><div class="g"><b>${esc(m.ti(r))}</b><span class="muted small">${esc(m.su(r))}</span></div>${ic('edit', 'sm')}</div>`).join('') || '<p class="muted">No records.</p>'}</div></div>`; }
function formFor(k, r) { const m = MOD[k]; return `<form data-f="adm" data-k="${k}"><input type="hidden" name="_id" value="${r ? r.id : ''}">${m.f.map(f => { const v = r ? r[f.k] : ''; const id = 'f_' + f.k; return `<label class="lbl" for="${id}">${f.l}</label>` + (f.t === 'a' ? `<textarea class="inp" id="${id}" name="${f.k}">${esc(v)}</textarea>` : f.t === 's' ? `<select class="inp" id="${id}" name="${f.k}">${f.o.map(o => `<option ${v === o ? 'selected' : ''}>${esc(o)}</option>`).join('')}</select>` : f.t === 'd' ? `<input class="inp" id="${id}" name="${f.k}" type="datetime-local" value="${v ? toLocalInput(v) : toLocalInput(new Date().toISOString())}">` : `<input class="inp" id="${id}" name="${f.k}" type="${f.t === 'n' ? 'number' : 'text'}" value="${esc(v)}">`); }).join('')}<div style="height:14px"></div><button class="btn btn-gold">${r ? 'Save changes' : 'Create'}</button>${r ? `<button type="button" class="btn btn-red" style="margin-top:8px" data-a="admDel" data-k="${k}" data-id="${r.id}">${k === 'announcements' ? 'Archive' : 'Delete'}</button>` : ''}</form>`; }
A.admNew = d => sheet(`<h3>New ${MOD[d.k].t.replace(/s$/, '')}</h3>` + formFor(d.k, null));
A.admEdit = d => sheet(`<h3>Edit</h3>` + formFor(d.k, S.db[MOD[d.k].col].find(r => r.id === d.id)));
FORMS.adm = (d, f) => { const k = f.dataset.k, m = MOD[k], col = S.db[m.col]; const rec = d._id ? col.find(r => r.id === d._id) : Object.assign({ id: uid(k[0]) }, clone(m.blank)); const req = m.f[0].k; if (!String(d[req] || '').trim()) return toast(m.f[0].l + ' is required'); m.f.forEach(x => { let v = d[x.k]; if (x.t === 'd') v = new Date(v).toISOString(); if (x.t === 'n') v = +v || 0; rec[x.k] = v; }); if (!d._id) col.push(rec); save(); logAudit((d._id ? 'Updated ' : 'Created ') + m.t + ': ' + m.ti(rec)); closeSheet(); render(); toast('Saved'); };
A.admDel = d => { const m = MOD[d.k]; const r = S.db[m.col].find(x => x.id === d.id); confirmBox(`${d.k === 'announcements' ? 'Archive' : 'Permanently delete'} "${m.ti(r)}"?`, () => { if (d.k === 'announcements') r.status = 'Archived'; else S.db[m.col] = S.db[m.col].filter(x => x.id !== d.id); logAudit((d.k === 'announcements' ? 'Archived ' : 'Deleted ') + m.t + ': ' + m.ti(r)); render(); toast('Done'); }); };
const ADMS = {
  giving: () => { const l = S.db.transactions.slice().sort((a, b) => new Date(b.date) - new Date(a.date)); return `<div class="pad"><div class="notice">⚠️ <span>Confidential financial data. Access limited to authorised roles; every status change is audited.</span></div><button class="btn btn-gold sm" data-a="recNew" style="margin-bottom:10px">+ Record offering</button><div class="card">${l.map(x => `<div class="row tap" data-a="txAdm" data-id="${x.id}"><div class="g"><b>${money(x.amount)} · ${fundName(x.fund)}</b><span class="muted small">${x.mc} · ${fd(x.date)} · ${x.ref}</span></div>${badge(x.status, stClass(x.status))}</div>`).join('')}</div></div>`; },
  pledges: () => `<div class="pad"><div class="card">${S.db.pledges.map(p => `<div class="row"><div class="g"><b>${esc(p.title)}</b><span class="muted small">${p.mc} · ${money(pledgePaid(p))} / ${money(p.total)} (${pledgePct(p)}%)</span></div><button class="btn btn-ghost sm" data-a="pledgePay" data-id="${p.id}">Record payment</button></div>`).join('')}</div></div>`,
  notifs: () => `<div class="pad"><div class="notice">ⓘ Demo: adds an in-app notification locally. Production uses FCM via a trusted backend.</div><form data-f="notif"><label class="lbl">Title</label><input class="inp" name="title" required><label class="lbl">Message</label><textarea class="inp" name="body" required></textarea><label class="lbl">Category</label><select class="inp" name="type">${['announcements', 'events', 'live', 'jumuiya', 'admin'].map(x => `<option>${x}</option>`).join('')}</select><div style="height:14px"></div><button class="btn btn-gold">Send notification</button></form></div>`,
  prayers: () => { const l = S.db.prayers.filter(x => x.privacy !== 'Confidential' || can('confidential')); return `<div class="pad">${!can('confidential') ? '<div class="notice">🔒 Confidential requests are hidden: only authorised pastoral staff can view them.</div>' : ''}<div class="card">${l.map(x => `<div class="row"><div class="g"><b style="white-space:normal;font-weight:500">${esc(x.text)}</b><span class="muted small">${x.privacy === 'Public' || can('confidential') ? x.mc : 'Anonymous'} · ${x.privacy} · ${x.status}</span></div><button class="btn btn-ghost sm" data-a="prStatus" data-id="${x.id}">Update</button></div>`).join('')}</div></div>`; },
  attendance: () => { const c = S.db.checkin; return `<div class="pad"><div class="card"><b>Service check-in</b><p class="muted small" style="margin:6px 0">${c.open ? `Open for <b>${esc(c.service)}</b>. Code: <b style="font-size:22px;letter-spacing:3px">${c.code}</b>` : 'Check-in is closed.'}</p><button class="btn ${c.open ? 'btn-red' : 'btn-gold'}" data-a="toggleCheckin">${c.open ? 'Close check-in' : 'Open check-in now'}</button></div><div class="card"><div class="b" style="margin-bottom:6px">Weekly attendance</div>${barChart(S.db.agg.months, S.db.agg.attendance)}</div></div>`; },
  opps: () => `<div class="pad"><div class="card"><div class="b" style="margin-bottom:6px">Applications</div>${S.applications.length ? S.applications.map(a => `<div class="row"><div class="g"><b>${esc((S.db.opps.find(o => o.id === a.opp) || {}).name)}</b><span class="muted small">${a.mc} · ${esc(a.msg)}</span></div>${badge(a.status, stClass(a.status) || 'warn')}<button class="btn btn-ghost sm" data-a="appSet" data-id="${a.id}">Review</button></div>`).join('') : '<p class="muted">No applications yet.</p>'}</div><button class="btn btn-ghost" data-a="admMod" data-k="opps">Manage opportunities</button></div>`,
  roles: () => `<div class="pad"><div class="notice">⚠️ <span>Read-only demo view. In production roles are stored as server-side claims and cannot be changed from the app.</span></div>${Object.entries(ROLES).map(([k, r]) => `<div class="card"><b>${r.label}</b><p class="muted small" style="margin-top:4px">${r.perms.includes('*') ? 'All permissions' : r.perms.join(', ') || 'Member features only'}</p><p class="small muted">Accounts: ${S.creds.filter(c => c.role === k).map(c => c.code).join(', ') || '—'}</p></div>`).join('')}</div>`,
  reports: () => { const r = UI.rr || '12', n = +r, a = S.db.agg, fl = UI.rf || 'all', ms = a.months.slice(-n), gv = ms.map((_, i) => (fl === 'all' ? FUNDS.reduce((s, f) => s + a.giving[f.id].slice(-n)[i], 0) : a.giving[fl].slice(-n)[i])), mem = S.db.members.slice().sort((x, y) => new Date(x.joined) - new Date(y.joined)), growth = ms.map((_, i) => { const d = new Date(); d.setMonth(d.getMonth() - (n - 1 - i) + 1, 0); return mem.filter(m => new Date(m.joined) <= d).length; }), fundTot = FUNDS.map(f => a.giving[f.id].slice(-n).reduce((s, v) => s + v, 0));
  return `<div class="pad"><div class="notice">ⓘ Sample analytics (demo data). Individual member finances are never shown here.</div><div class="inl"><select class="inp" data-in="rr"><option value="3" ${r === '3' ? 'selected' : ''}>Last 3 months</option><option value="6" ${r === '6' ? 'selected' : ''}>Last 6 months</option><option value="12" ${r === '12' ? 'selected' : ''}>Last 12 months</option></select><select class="inp" data-in="rf"><option value="all">All funds</option>${FUNDS.map(f => `<option value="${f.id}" ${fl === f.id ? 'selected' : ''}>${f.name}</option>`).join('')}</select></div><div style="height:12px"></div>
<div class="card"><div class="b">Giving over time</div>${barChart(ms, gv, v => money(v))}</div><div class="card"><div class="b">Giving by fund</div>${barChart(FUNDS.map(f => f.name), fundTot, v => money(v))}</div><div class="card"><div class="b">Membership growth</div>${lineChart(ms, growth)}</div><div class="card"><div class="b">Attendance</div>${lineChart(ms, a.attendance.slice(-n))}</div><div class="card"><div class="b">Event registrations</div>${barChart(S.db.events.map(e => e.title), S.db.events.map(e => e.baseReg + (S.rsvps[e.id] ? 1 : 0)))}</div><div class="card"><div class="b">Pledge completion</div>${S.db.pledges.map(p => `<div style="margin:8px 0"><div class="small">${esc(p.title)} · ${pledgePct(p)}% · outstanding ${money(p.total - pledgePaid(p))}</div><div class="bar"><i style="width:${pledgePct(p)}%"></i></div></div>`).join('')}</div><div class="card"><div class="b">Volunteer participation</div>${barChart(Object.keys(a.volunteerByMinistry), Object.values(a.volunteerByMinistry))}</div><button class="btn btn-gold" data-a="exportRep">${ic('dl', 'sm')} Export summary (CSV)</button></div>`; },
  audit: () => `<div class="pad"><div class="card">${S.db.audit.map(a => `<div class="row"><div class="g"><b style="white-space:normal;font-weight:500;font-size:13px">${esc(a.action)}</b><span class="muted small">${a.who} · ${fdt(a.date)}</span></div></div>`).join('')}</div></div>`,
  settings: () => { const c = S.db.church; return `<div class="pad"><form data-f="church">${[['name', 'Church name'], ['phone', 'Phone'], ['email', 'Email'], ['address', 'Address'], ['youtube', 'YouTube channel / playlist URL'], ['currency', 'Currency code (e.g. TZS)']].map(([k, l]) => `<label class="lbl">${l}</label><input class="inp" name="${k}" value="${esc(c[k])}" required>`).join('')}<label class="check"><input type="checkbox" name="marketplace" ${c.marketplace ? 'checked' : ''}> Enable Marketplace module</label><button class="btn btn-gold">Save settings</button></form></div>`; }
};
FORMS.church = d => { const c = S.db.church; ['name', 'phone', 'email', 'address', 'youtube', 'currency'].forEach(k => c[k] = d[k].trim()); c.marketplace = !!d.marketplace; save(); logAudit('Updated church settings'); toast('Settings saved'); render(); };
A.admMod = d => go('adm', { id: d.k });
A.recNew = () => sheet(`<h3>Record offering</h3><form data-f="rec"><label class="lbl">Member code</label><input class="inp" name="mc" value="MEM10045" required><label class="lbl">Fund</label><select class="inp" name="fund">${FUNDS.map(f => `<option value="${f.id}">${f.name}</option>`).join('')}</select><label class="lbl">Amount</label><input class="inp" name="amount" type="number" min="1" required><label class="lbl">Method</label><select class="inp" name="method">${['Cash (Office)', 'M-Pesa', 'Bank Transfer', 'Tigo Pesa', 'Airtel Money'].map(x => `<option>${x}</option>`).join('')}</select><div style="height:14px"></div><button class="btn btn-gold">Record (verified by treasurer)</button></form>`);
FORMS.rec = d => { const mc = d.mc.trim().toUpperCase(); if (!S.db.members.some(m => m.code === mc)) return toast('Unknown member code'); S.db.transactions.unshift({ id: 'TX-' + (2000 + S.db.transactions.length), mc, fund: d.fund, amount: +d.amount, date: new Date().toISOString(), method: d.method, ref: 'OFF-' + Date.now().toString().slice(-6), status: 'Verified', pledge: '', source: 'Office entry by ' + S.session.code }); logAudit('Recorded giving ' + money(+d.amount) + ' for ' + mc); closeSheet(); render(); toast('Record added'); };
A.txAdm = d => { const x = S.db.transactions.find(t => t.id === d.id); sheet(`<h3>${x.id}</h3><p class="muted">${money(x.amount)} · ${fundName(x.fund)} · ${x.status}</p><div class="inl" style="margin-top:12px"><button class="btn btn-gold" data-a="txSet" data-id="${x.id}" data-s="Verified">Verify</button><button class="btn btn-red" data-a="txSet" data-id="${x.id}" data-s="Rejected">Reject</button></div>`); };
A.txSet = d => { const x = S.db.transactions.find(t => t.id === d.id); x.status = d.s; logAudit(`${d.s} giving record ${x.id}`); closeSheet(); render(); toast('Status updated'); };
A.pledgePay = d => sheet(`<h3>Record pledge payment</h3><form data-f="pp"><input type="hidden" name="id" value="${d.id}"><label class="lbl">Amount</label><input class="inp" name="amount" type="number" min="1" required><div style="height:14px"></div><button class="btn btn-gold">Record</button></form>`);
FORMS.pp = d => { const p = S.db.pledges.find(x => x.id === d.id); const a = +d.amount; if (a > p.total - pledgePaid(p)) return toast('Exceeds remaining balance'); S.db.transactions.unshift({ id: 'TX-' + (3000 + S.db.transactions.length), mc: p.mc, fund: p.fund, amount: a, date: new Date().toISOString(), method: 'Office entry', ref: 'PLG-' + Date.now().toString().slice(-6), status: 'Verified', pledge: p.id, source: 'Recorded by ' + S.session.code }); logAudit('Recorded pledge payment for ' + p.title); closeSheet(); render(); toast('Payment recorded'); };
FORMS.notif = (d, f) => { S.db.notifications.unshift({ id: uid('n'), type: d.type, title: d.title, body: d.body, date: new Date().toISOString(), read: false }); logAudit('Sent notification: ' + d.title); f.reset(); toast('Notification added (demo, local only)'); };
A.prStatus = d => { const x = S.db.prayers.find(p => p.id === d.id); x.status = pick(['Received', 'Being prayed for', 'Pastor assigned', 'Answered'], ['Received', 'Being prayed for', 'Pastor assigned', 'Answered'].indexOf(x.status) + 1); logAudit('Updated prayer request status'); save(); render(); };
A.toggleCheckin = () => { const c = S.db.checkin; c.open = !c.open; if (c.open) { c.code = String(Math.floor(100000 + Math.random() * 900000)); c.service = 'Sunday Worship Service'; } logAudit((c.open ? 'Opened' : 'Closed') + ' attendance check-in'); save(); render(); };
A.appSet = d => { const a = S.applications.find(x => x.id === d.id); a.status = a.status === 'Pending' ? 'Approved' : a.status === 'Approved' ? 'Declined' : 'Pending'; logAudit('Reviewed volunteer application'); save(); render(); };
A.exportRep = () => { const a = S.db.agg; dlFile('church-report-demo.csv', ['Month,' + FUNDS.map(f => f.name).join(',') + ',Attendance', ...a.months.map((m, i) => [m, ...FUNDS.map(f => a.giving[f.id][i]), a.attendance[i]].join(','))].join('\n') + '\n\nDEMO sample data'); toast('Report downloaded'); };

/* ---------- boot ---------- */
render();
